<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Neon Brick Breaker</title>
<style>
  :root {
    color-scheme: dark;
    --cyan: #4dfcff;
    --pink: #ff3cac;
    --violet: #9b5cff;
  }

  * {
    box-sizing: border-box;
  }

  html, body {
    width: 100%;
    height: 100%;
    margin: 0;
    overflow: hidden;
    background:
      radial-gradient(circle at 20% 15%, rgba(76, 0, 130, 0.22), transparent 32%),
      radial-gradient(circle at 80% 80%, rgba(0, 229, 255, 0.12), transparent 35%),
      #02030b;
    font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
      "Segoe UI", sans-serif;
  }

  body {
    display: grid;
    place-items: center;
    user-select: none;
    overscroll-behavior: none;
  }

  #game {
    display: block;
    outline: none;
    border: 1px solid rgba(77, 252, 255, 0.28);
    border-radius: 16px;
    background: #050716;
    box-shadow:
      0 0 28px rgba(77, 252, 255, 0.14),
      0 0 80px rgba(155, 92, 255, 0.12),
      inset 0 0 30px rgba(0, 0, 0, 0.65);
    touch-action: none;
    -webkit-tap-highlight-color: transparent;
  }
</style>
</head>
<body>
<canvas
  id="game"
  width="1000"
  height="650"
  tabindex="0"
  aria-label="Neon Brick Breaker. Use mouse, touch, arrow keys, or A and D to move."
></canvas>

<script>
(() => {
  "use strict";

  const canvas = document.getElementById("game");
  const ctx = canvas.getContext("2d");

  const WIDTH = 1000;
  const HEIGHT = 650;
  const FIELD_TOP = 72;
  const WALL = 12;
  const MAX_LEVEL = 3;
  const TAU = Math.PI * 2;

  const COLORS = {
    cyan: "#4dfcff",
    pink: "#ff3cac",
    violet: "#9b5cff",
    yellow: "#ffe66d",
    green: "#62ffb0",
    red: "#ff526b",
    white: "#f4fbff"
  };

  const levelData = [
    {
      rows: 5,
      cols: 10,
      speed: 410,
      paddleWidth: 148,
      palette: [COLORS.cyan, COLORS.violet, COLORS.pink, COLORS.yellow, COLORS.green]
    },
    {
      rows: 6,
      cols: 11,
      speed: 455,
      paddleWidth: 132,
      palette: [COLORS.pink, COLORS.violet, COLORS.cyan, COLORS.green, COLORS.yellow, COLORS.red]
    },
    {
      rows: 7,
      cols: 12,
      speed: 505,
      paddleWidth: 116,
      palette: [COLORS.red, COLORS.pink, COLORS.violet, COLORS.cyan, COLORS.green, COLORS.yellow]
    }
  ];

  let state = "start";
  let score = 0;
  let lives = 3;
  let level = 0;
  let levelTimer = 0;
  let lastTime = performance.now();
  let wallSoundTime = 0;
  let shake = 0;

  const keys = {
    left: false,
    right: false
  };

  const pointer = {
    active: false,
    x: WIDTH / 2
  };

  const paddle = {
    x: WIDTH / 2 - 70,
    y: HEIGHT - 54,
    width: 140,
    height: 16,
    speed: 760,
    velocity: 0
  };

  const ball = {
    x: WIDTH / 2,
    y: HEIGHT - 75,
    radius: 9,
    vx: 0,
    vy: 0,
    speed: 410,
    stuck: true,
    trail: []
  };

  let bricks = [];
  let particles = [];
  let stars = [];
  let audioContext = null;

  function resizeCanvas() {
    const margin = 20;
    const availableWidth = Math.max(240, window.innerWidth - margin);
    const availableHeight = Math.max(240, window.innerHeight - margin);
    const scale = Math.min(availableWidth / WIDTH, availableHeight / HEIGHT);
    const dpr = Math.min(window.devicePixelRatio || 1, 2.5);

    canvas.style.width = `${Math.floor(WIDTH * scale)}px`;
    canvas.style.height = `${Math.floor(HEIGHT * scale)}px`;
    canvas.width = Math.floor(WIDTH * dpr);
    canvas.height = Math.floor(HEIGHT * dpr);

    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  function createStars() {
    stars = Array.from({ length: 100 }, () => ({
      x: Math.random() * WIDTH,
      y: FIELD_TOP + Math.random() * (HEIGHT - FIELD_TOP),
      radius: Math.random() * 1.5 + 0.25,
      alpha: Math.random() * 0.6 + 0.15,
      phase: Math.random() * TAU,
      speed: Math.random() * 1.5 + 0.5
    }));
  }

  function initAudio() {
    if (!audioContext) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) audioContext = new AudioCtx();
    }

    if (audioContext?.state === "suspended") {
      audioContext.resume();
    }
  }

  function tone(frequency, duration, type = "sine", volume = 0.04, slide = 1, delay = 0) {
    if (!audioContext) return;

    const start = audioContext.currentTime + delay;
    const oscillator = audioContext.createOscillator();
    const gain = audioContext.createGain();

    oscillator.type = type;
    oscillator.frequency.setValueAtTime(Math.max(20, frequency), start);
    oscillator.frequency.exponentialRampToValueAtTime(
      Math.max(20, frequency * slide),
      start + duration
    );

    gain.gain.setValueAtTime(0.0001, start);
    gain.gain.exponentialRampToValueAtTime(volume, start + 0.006);
    gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);

    oscillator.connect(gain);
    gain.connect(audioContext.destination);
    oscillator.start(start);
    oscillator.stop(start + duration + 0.02);
  }

  function playSound(name) {
    switch (name) {
      case "brick":
        tone(260 + Math.random() * 100, 0.065, "square", 0.035, 1.7);
        tone(620 + Math.random() * 180, 0.04, "sine", 0.02, 0.8);
        break;
      case "damage":
        tone(170, 0.055, "sawtooth", 0.025, 1.25);
        break;
      case "paddle":
        tone(145, 0.075, "triangle", 0.04, 1.8);
        break;
      case "wall":
        if (performance.now() - wallSoundTime > 40) {
          wallSoundTime = performance.now();
          tone(460, 0.025, "sine", 0.014, 1.2);
        }
        break;
      case "launch":
        tone(220, 0.08, "triangle", 0.035, 2.1);
        break;
      case "lose":
        tone(180, 0.25, "sawtooth", 0.045, 0.35);
        tone(90, 0.3, "triangle", 0.035, 0.5, 0.08);
        break;
      case "level":
        tone(330, 0.13, "triangle", 0.04, 1.5);
        tone(494, 0.15, "triangle", 0.04, 1.35, 0.1);
        tone(659, 0.2, "triangle", 0.04, 1.2, 0.2);
        break;
      case "victory":
        tone(392, 0.3, "triangle", 0.05, 1.02);
        tone(523, 0.3, "triangle", 0.05, 1.02, 0.15);
        tone(659, 0.3, "triangle", 0.05, 1.02, 0.3);
        tone(784, 0.55, "sine", 0.05, 1.02, 0.45);
        break;
    }
  }

  function shouldCreateBrick(row, col, config) {
    if (level === 0) return true;

    if (level === 1) {
      const center = (config.cols - 1) / 2;
      return !(row > 1 && row < 5 && Math.abs(col - center) < 1.25);
    }

    const edge = col === 0 || col === config.cols - 1;
    const diagonal = (row + col) % 3 !== 1;
    return edge || diagonal;
  }

  function buildLevel() {
    const config = levelData[level];
    bricks = [];

    const sideMargin = 54;
    const gap = level === 2 ? 5 : 7;
    const brickHeight = 27;
    const totalWidth = WIDTH - sideMargin * 2;
    const brickWidth = (totalWidth - gap * (config.cols - 1)) / config.cols;
    const startY = 105;

    for (let row = 0; row < config.rows; row++) {
      for (let col = 0; col < config.cols; col++) {
        if (!shouldCreateBrick(row, col, config)) continue;

        let hp = 1;
        if (level === 1 && (row + col) % 7 === 0) hp = 2;
        if (level === 2 && (row === 0 || (row + col) % 5 === 0)) hp = 2;

        bricks.push({
          x: sideMargin + col * (brickWidth + gap),
          y: startY + row * (brickHeight + gap),
          width: brickWidth,
          height: brickHeight,
          color: config.palette[row % config.palette.length],
          hp,
          maxHp: hp,
          alive: true,
          flash: 0
        });
      }
    }

    paddle.width = config.paddleWidth;
    paddle.x = WIDTH / 2 - paddle.width / 2;
    paddle.velocity = 0;

    ball.speed = config.speed;
    resetBall(true);
  }

  function resetBall(stuck = true) {
    ball.stuck = stuck;
    ball.vx = 0;
    ball.vy = 0;
    ball.x = paddle.x + paddle.width / 2;
    ball.y = paddle.y - ball.radius - 3;
    ball.trail.length = 0;
  }

  function launchBall() {
    if (state !== "playing" || !ball.stuck) return;

    const angle = (Math.random() * 1.05) - 0.525;
    ball.vx = Math.sin(angle) * ball.speed;
    ball.vy = -Math.cos(angle) * ball.speed;
    ball.stuck = false;
    playSound("launch");
  }

  function newGame() {
    score = 0;
    lives = 3;
    level = 0;
    particles.length = 0;
    state = "playing";
    buildLevel();
    launchBall();
  }

  function startAction() {
    initAudio();

    if (state === "start" || state === "gameover" || state === "victory") {
      newGame();
    } else if (state === "playing" && ball.stuck) {
      launchBall();
    } else if (state === "paused") {
      state = "playing";
    }
  }

  function togglePause() {
    if (state === "playing") {
      state = "paused";
    } else if (state === "paused") {
      state = "playing";
    }
  }

  function pointerPosition(event) {
    const rect = canvas.getBoundingClientRect();
    return {
      x: (event.clientX - rect.left) * WIDTH / rect.width,
      y: (event.clientY - rect.top) * HEIGHT / rect.height
    };
  }

  canvas.addEventListener("pointerdown", event => {
    event.preventDefault();
    const position = pointerPosition(event);
    pointer.active = true;
    pointer.x = position.x;

    try {
      canvas.setPointerCapture(event.pointerId);
    } catch (_) {}

    canvas.focus();
    startAction();
  });

  canvas.addEventListener("pointermove", event => {
    const position = pointerPosition(event);
    pointer.active = true;
    pointer.x = position.x;
  });

  canvas.addEventListener("contextmenu", event => event.preventDefault());

  window.addEventListener("keydown", event => {
    const key = event.key.toLowerCase();

    if (key === "arrowleft" || key === "a") {
      keys.left = true;
      pointer.active = false;
      event.preventDefault();
    }

    if (key === "arrowright" || key === "d") {
      keys.right = true;
      pointer.active = false;
      event.preventDefault();
    }

    if ((key === " " || key === "enter") && !event.repeat) {
      event.preventDefault();
      startAction();
    }

    if (key === "p" && !event.repeat) {
      event.preventDefault();
      togglePause();
    }
  });

  window.addEventListener("keyup", event => {
    const key = event.key.toLowerCase();
    if (key === "arrowleft" || key === "a") keys.left = false;
    if (key === "arrowright" || key === "d") keys.right = false;
  });

  document.addEventListener("visibilitychange", () => {
    if (document.hidden && state === "playing") state = "paused";
  });

  window.addEventListener("resize", resizeCanvas);

  function updatePaddle(dt) {
    const previousX = paddle.x;

    if (keys.left && !keys.right) {
      paddle.x -= paddle.speed * dt;
    } else if (keys.right && !keys.left) {
      paddle.x += paddle.speed * dt;
    } else if (pointer.active) {
      const target = pointer.x - paddle.width / 2;
      paddle.x += (target - paddle.x) * Math.min(1, dt * 18);
    }

    paddle.x = Math.max(WALL, Math.min(WIDTH - WALL - paddle.width, paddle.x));
    paddle.velocity = (paddle.x - previousX) / Math.max(dt, 0.001);

    if (ball.stuck) {
      ball.x = paddle.x + paddle.width / 2;
      ball.y = paddle.y - ball.radius - 3;
    }
  }

  function circleRectCollision(circle, rect) {
    const closestX = Math.max(rect.x, Math.min(circle.x, rect.x + rect.width));
    const closestY = Math.max(rect.y, Math.min(circle.y, rect.y + rect.height));
    const dx = circle.x - closestX;
    const dy = circle.y - closestY;
    const distanceSquared = dx * dx + dy * dy;

    if (distanceSquared > circle.radius * circle.radius) return null;

    if (distanceSquared > 0.000001) {
      const distance = Math.sqrt(distanceSquared);
      return {
        nx: dx / distance,
        ny: dy / distance,
        penetration: circle.radius - distance
      };
    }

    const left = circle.x - rect.x;
    const right = rect.x + rect.width - circle.x;
    const top = circle.y - rect.y;
    const bottom = rect.y + rect.height - circle.y;
    const minimum = Math.min(left, right, top, bottom);

    if (minimum === left) return { nx: -1, ny: 0, penetration: circle.radius + left };
    if (minimum === right) return { nx: 1, ny: 0, penetration: circle.radius + right };
    if (minimum === top) return { nx: 0, ny: -1, penetration: circle.radius + top };
    return { nx: 0, ny: 1, penetration: circle.radius + bottom };
  }

  function reflectBall(normalX, normalY) {
    const dot = ball.vx * normalX + ball.vy * normalY;
    if (dot < 0) {
      ball.vx -= 2 * dot * normalX;
      ball.vy -= 2 * dot * normalY;
    }
  }

  function spawnParticles(x, y, color, count = 16) {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * TAU;
      const speed = 70 + Math.random() * 260;
      const life = 0.35 + Math.random() * 0.55;

      particles.push({
        x,
        y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        gravity: 170 + Math.random() * 120,
        size: 1.5 + Math.random() * 4,
        life,
        maxLife: life,
        color,
        rotation: Math.random() * TAU,
        spin: (Math.random() - 0.5) * 12
      });
    }
  }

  function updateParticles(dt) {
    for (let i = particles.length - 1; i >= 0; i--) {
      const particle = particles[i];
      particle.life -= dt;

      if (particle.life <= 0) {
        particles.splice(i, 1);
        continue;
      }

      particle.vy += particle.gravity * dt;
      particle.vx *= Math.pow(0.985, dt * 60);
      particle.x += particle.vx * dt;
      particle.y += particle.vy * dt;
      particle.rotation += particle.spin * dt;
    }
  }

  function loseBall() {
    lives--;
    shake = 8;
    playSound("lose");

    if (lives <= 0) {
      state = "gameover";
      ball.stuck = true;
      return;
    }

    resetBall(true);
  }

  function completeLevel() {
    state = "levelclear";
    levelTimer = 1.8;
    ball.stuck = true;
    playSound("level");
  }

  function handleBrickCollision() {
    for (const brick of bricks) {
      if (!brick.alive) continue;

      const collision = circleRectCollision(ball, brick);
      if (!collision) continue;

      ball.x += collision.nx * (collision.penetration + 0.2);
      ball.y += collision.ny * (collision.penetration + 0.2);
      reflectBall(collision.nx, collision.ny);

      brick.hp--;
      brick.flash = 1;
      shake = Math.max(shake, 2.5);

      if (brick.hp <= 0) {
        brick.alive = false;
        score += 100 * (level + 1) * brick.maxHp;
        spawnParticles(
          brick.x + brick.width / 2,
          brick.y + brick.height / 2,
          brick.color,
          brick.maxHp > 1 ? 24 : 16
        );
        playSound("brick");

        if (bricks.every(item => !item.alive)) {
          completeLevel();
        }
      } else {
        score += 25 * (level + 1);
        spawnParticles(ball.x, ball.y, brick.color, 6);
        playSound("damage");
      }

      return;
    }
  }

  function updateBall(dt) {
    if (ball.stuck || state !== "playing") return;

    const velocity = Math.hypot(ball.vx, ball.vy);
    const steps = Math.max(1, Math.ceil(velocity * dt / (ball.radius * 0.65)));
    const stepTime = dt / steps;

    for (let step = 0; step < steps; step++) {
      ball.x += ball.vx * stepTime;
      ball.y += ball.vy * stepTime;

      if (ball.x - ball.radius < WALL) {
        ball.x = WALL + ball.radius;
        ball.vx = Math.abs(ball.vx);
        playSound("wall");
      } else if (ball.x + ball.radius > WIDTH - WALL) {
        ball.x = WIDTH - WALL - ball.radius;
        ball.vx = -Math.abs(ball.vx);
        playSound("wall");
      }

      if (ball.y - ball.radius < FIELD_TOP) {
        ball.y = FIELD_TOP + ball.radius;
        ball.vy = Math.abs(ball.vy);
        playSound("wall");
      }

      if (
        ball.vy > 0 &&
        ball.x + ball.radius > paddle.x &&
        ball.x - ball.radius < paddle.x + paddle.width &&
        ball.y + ball.radius > paddle.y &&
        ball.y - ball.radius < paddle.y + paddle.height
      ) {
        ball.y = paddle.y - ball.radius - 0.5;

        const relative =
          (ball.x - (paddle.x + paddle.width / 2)) / (paddle.width / 2);
        const normalized = Math.max(-1, Math.min(1, relative));
        const maximumAngle = 67 * Math.PI / 180;
        const angle = normalized * maximumAngle;
        const newSpeed = Math.min(ball.speed * 1.28, Math.hypot(ball.vx, ball.vy) * 1.012);

        ball.vx = Math.sin(angle) * newSpeed + paddle.velocity * 0.05;
        ball.vy = -Math.abs(Math.cos(angle) * newSpeed);

        const correctedSpeed = Math.hypot(ball.vx, ball.vy);
        if (correctedSpeed > newSpeed * 1.08) {
          ball.vx *= newSpeed / correctedSpeed;
          ball.vy *= newSpeed / correctedSpeed;
        }

        playSound("paddle");
      }

      handleBrickCollision();
      if (state !== "playing") return;

      if (ball.y - ball.radius > HEIGHT) {
        loseBall();
        return;
      }
    }

    ball.trail.unshift({ x: ball.x, y: ball.y });
    if (ball.trail.length > 13) ball.trail.pop();
  }

  function update(dt) {
    shake *= Math.pow(0.06, dt);
    updateParticles(dt);

    for (const brick of bricks) {
      brick.flash = Math.max(0, brick.flash - dt * 5);
    }

    if (state === "playing") {
      updatePaddle(dt);
      updateBall(dt);
    } else if (state === "levelclear") {
      levelTimer -= dt;

      if (levelTimer <= 0) {
        if (level + 1 >= MAX_LEVEL) {
          state = "victory";
          playSound("victory");
        } else {
          level++;
          state = "playing";
          buildLevel();
          launchBall();
        }
      }
    }
  }

  function roundedRectPath(x, y, width, height, radius) {
    const r = Math.min(radius, width / 2, height / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + width, y, x + width, y + height, r);
    ctx.arcTo(x + width, y + height, x, y + height, r);
    ctx.arcTo(x, y + height, x, y, r);
    ctx.arcTo(x, y, x + width, y, r);
    ctx.closePath();
  }

  function drawBackground(time) {
    const gradient = ctx.createLinearGradient(0, 0, 0, HEIGHT);
    gradient.addColorStop(0, "#090b22");
    gradient.addColorStop(0.45, "#050716");
    gradient.addColorStop(1, "#02030a");
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, WIDTH, HEIGHT);

    const glow = ctx.createRadialGradient(
      WIDTH / 2, 260, 20,
      WIDTH / 2, 300, 620
    );
    glow.addColorStop(0, "rgba(105, 46, 255, 0.10)");
    glow.addColorStop(0.45, "rgba(0, 229, 255, 0.035)");
    glow.addColorStop(1, "rgba(0, 0, 0, 0)");
    ctx.fillStyle = glow;
    ctx.fillRect(0, FIELD_TOP, WIDTH, HEIGHT - FIELD_TOP);

    for (const star of stars) {
      const alpha = star.alpha * (0.65 + Math.sin(time * 0.001 * star.speed + star.phase) * 0.35);
      ctx.fillStyle = `rgba(190, 225, 255, ${alpha})`;
      ctx.beginPath();
      ctx.arc(star.x, star.y, star.radius, 0, TAU);
      ctx.fill();
    }

    ctx.strokeStyle = "rgba(77, 252, 255, 0.035)";
    ctx.lineWidth = 1;
    for (let y = FIELD_TOP; y < HEIGHT; y += 32) {
      ctx.beginPath();
      ctx.moveTo(WALL, y);
      ctx.lineTo(WIDTH - WALL, y);
      ctx.stroke();
    }

    const floorGradient = ctx.createLinearGradient(0, HEIGHT - 180, 0, HEIGHT);
    floorGradient.addColorStop(0, "rgba(155, 92, 255, 0)");
    floorGradient.addColorStop(1, "rgba(77, 252, 255, 0.045)");
    ctx.fillStyle = floorGradient;
    ctx.fillRect(0, HEIGHT - 180, WIDTH, 180);

    ctx.strokeStyle = "rgba(77, 252, 255, 0.25)";
    ctx.shadowColor = COLORS.cyan;
    ctx.shadowBlur = 10;
    ctx.beginPath();
    ctx.moveTo(WALL, FIELD_TOP);
    ctx.lineTo(WIDTH - WALL, FIELD_TOP);
    ctx.stroke();
    ctx.shadowBlur = 0;
  }

  function drawHUD() {
    ctx.save();

    ctx.fillStyle = "rgba(3, 5, 16, 0.82)";
    ctx.fillRect(0, 0, WIDTH, FIELD_TOP);

    ctx.textBaseline = "middle";

    ctx.font = "800 22px system-ui, sans-serif";
    ctx.fillStyle = COLORS.white;
    ctx.shadowColor = COLORS.cyan;
    ctx.shadowBlur = 12;
    ctx.fillText("NEON", 28, 35);

    const neonWidth = ctx.measureText("NEON").width;
    ctx.fillStyle = COLORS.pink;
    ctx.shadowColor = COLORS.pink;
    ctx.fillText(" BREAKER", 28 + neonWidth, 35);

    ctx.shadowBlur = 0;
    ctx.font = "700 17px ui-monospace, SFMono-Regular, Menlo, monospace";

    ctx.fillStyle = "rgba(205, 225, 255, 0.7)";
    ctx.fillText("SCORE", 390, 35);
    ctx.fillStyle = COLORS.cyan;
    ctx.fillText(String(score).padStart(6, "0"), 456, 35);

    ctx.fillStyle = "rgba(205, 225, 255, 0.7)";
    ctx.fillText("LEVEL", 620, 35);
    ctx.fillStyle = COLORS.yellow;
    ctx.fillText(`${level + 1}/${MAX_LEVEL}`, 684, 35);

    ctx.fillStyle = "rgba(205, 225, 255, 0.7)";
    ctx.fillText("LIVES", 795, 35);

    for (let i = 0; i < Math.max(0, lives); i++) {
      const x = 865 + i * 28;
      const ballGradient = ctx.createRadialGradient(x - 3, 31, 1, x, 35, 9);
      ballGradient.addColorStop(0, "#ffffff");
      ballGradient.addColorStop(0.35, COLORS.cyan);
      ballGradient.addColorStop(1, "#3569ff");
      ctx.fillStyle = ballGradient;
      ctx.shadowColor = COLORS.cyan;
      ctx.shadowBlur = 10;
      ctx.beginPath();
      ctx.arc(x, 35, 7, 0, TAU);
      ctx.fill();
    }

    ctx.restore();
  }

  function drawBricks() {
    for (const brick of bricks) {
      if (!brick.alive) continue;

      ctx.save();

      const alpha = brick.maxHp > 1 && brick.hp === 1 ? 0.72 : 1;
      const gradient = ctx.createLinearGradient(
        brick.x,
        brick.y,
        brick.x,
        brick.y + brick.height
      );

      gradient.addColorStop(0, brick.flash > 0 ? "#ffffff" : brick.color);
      gradient.addColorStop(0.5, brick.color);
      gradient.addColorStop(1, `${brick.color}88`);

      ctx.globalAlpha = alpha;
      ctx.fillStyle = gradient;
      ctx.shadowColor = brick.color;
      ctx.shadowBlur = 12 + brick.flash * 15;

      roundedRectPath(brick.x, brick.y, brick.width, brick.height, 6);
      ctx.fill();

      ctx.shadowBlur = 0;
      ctx.strokeStyle = "rgba(255, 255, 255, 0.5)";
      ctx.lineWidth = 1;
      roundedRectPath(brick.x + 0.5, brick.y + 0.5, brick.width - 1, brick.height - 1, 5);
      ctx.stroke();

      ctx.fillStyle = "rgba(255, 255, 255, 0.22)";
      roundedRectPath(brick.x + 5, brick.y + 4, brick.width - 10, 4, 2);
      ctx.fill();

      if (brick.maxHp > 1) {
        ctx.fillStyle = "rgba(4, 7, 20, 0.55)";
        roundedRectPath(
          brick.x + brick.width / 2 - 11,
          brick.y + brick.height / 2 - 2,
          22,
          4,
          2
        );
        ctx.fill();
      }

      ctx.restore();
    }
  }

  function drawPaddle() {
    ctx.save();

    ctx.shadowColor = COLORS.cyan;
    ctx.shadowBlur = 22;

    const gradient = ctx.createLinearGradient(
      paddle.x,
      paddle.y,
      paddle.x + paddle.width,
      paddle.y
    );
    gradient.addColorStop(0, COLORS.violet);
    gradient.addColorStop(0.25, COLORS.cyan);
    gradient.addColorStop(0.5, "#ffffff");
    gradient.addColorStop(0.75, COLORS.cyan);
    gradient.addColorStop(1, COLORS.pink);

    ctx.fillStyle = gradient;
    roundedRectPath(paddle.x, paddle.y, paddle.width, paddle.height, 8);
    ctx.fill();

    ctx.shadowBlur = 0;
    ctx.fillStyle = "rgba(255, 255, 255, 0.65)";
    roundedRectPath(paddle.x + 12, paddle.y + 3, paddle.width - 24, 3, 2);
    ctx.fill();

    ctx.restore();
  }

  function drawBall() {
    ctx.save();

    for (let i = ball.trail.length - 1; i >= 0; i--) {
      const point = ball.trail[i];
      const progress = 1 - i / ball.trail.length;
      ctx.globalAlpha = progress * 0.15;
      ctx.fillStyle = i % 2 ? COLORS.cyan : COLORS.pink;
      ctx.beginPath();
      ctx.arc(point.x, point.y, ball.radius * progress, 0, TAU);
      ctx.fill();
    }

    ctx.globalAlpha = 1;
    ctx.shadowColor = COLORS.cyan;
    ctx.shadowBlur = 24;

    const gradient = ctx.createRadialGradient(
      ball.x - 3,
      ball.y - 4,
      1,
      ball.x,
      ball.y,
      ball.radius
    );
    gradient.addColorStop(0, "#ffffff");
    gradient.addColorStop(0.28, "#dfffff");
    gradient.addColorStop(0.62, COLORS.cyan);
    gradient.addColorStop(1, "#3758ff");

    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.radius, 0, TAU);
    ctx.fill();

    ctx.restore();
  }

  function drawParticles() {
    for (const particle of particles) {
      const alpha = Math.max(0, particle.life / particle.maxLife);

      ctx.save();
      ctx.translate(particle.x, particle.y);
      ctx.rotate(particle.rotation);
      ctx.globalAlpha = alpha;
      ctx.fillStyle = particle.color;
      ctx.shadowColor = particle.color;
      ctx.shadowBlur = 10;
      ctx.fillRect(
        -particle.size / 2,
        -particle.size / 2,
        particle.size * 1.6,
        particle.size
      );
      ctx.restore();
    }
  }

  function drawReadyPrompt(time) {
    if (state !== "playing" || !ball.stuck) return;

    const alpha = 0.62 + Math.sin(time * 0.006) * 0.28;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.font = "700 15px system-ui, sans-serif";
    ctx.textAlign = "center";
    ctx.fillStyle = COLORS.cyan;
    ctx.shadowColor = COLORS.cyan;
    ctx.shadowBlur = 12;
    ctx.fillText("BALL READY — CLICK, TAP, OR PRESS SPACE", WIDTH / 2, HEIGHT - 92);
    ctx.restore();
  }

  function drawOverlay(title, subtitle, accent, lines = []) {
    ctx.save();

    ctx.fillStyle = "rgba(1, 2, 10, 0.78)";
    ctx.fillRect(0, FIELD_TOP, WIDTH, HEIGHT - FIELD_TOP);

    const panelWidth = 590;
    const panelHeight = 330;
    const panelX = (WIDTH - panelWidth) / 2;
    const panelY = FIELD_TOP + (HEIGHT - FIELD_TOP - panelHeight) / 2;

    const panelGradient = ctx.createLinearGradient(
      panelX,
      panelY,
      panelX,
      panelY + panelHeight
    );
    panelGradient.addColorStop(0, "rgba(15, 18, 48, 0.97)");
    panelGradient.addColorStop(1, "rgba(4, 6, 22, 0.97)");

    ctx.fillStyle = panelGradient;
    ctx.strokeStyle = accent;
    ctx.lineWidth = 1.5;
    ctx.shadowColor = accent;
    ctx.shadowBlur = 28;

    roundedRectPath(panelX, panelY, panelWidth, panelHeight, 22);
    ctx.fill();
    ctx.stroke();

    ctx.shadowBlur = 0;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";

    ctx.font = "900 52px system-ui, sans-serif";
    ctx.fillStyle = COLORS.white;
    ctx.shadowColor = accent;
    ctx.shadowBlur = 22;
    ctx.fillText(title, WIDTH / 2, panelY + 78);

    ctx.shadowBlur = 0;
    ctx.font = "700 19px system-ui, sans-serif";
    ctx.fillStyle = accent;
    ctx.fillText(subtitle, WIDTH / 2, panelY + 125);

    ctx.font = "500 16px system-ui, sans-serif";
    ctx.fillStyle = "rgba(220, 235, 255, 0.78)";

    lines.forEach((line, index) => {
      ctx.fillText(line, WIDTH / 2, panelY + 171 + index * 29);
    });

    ctx.font = "800 15px system-ui, sans-serif";
    ctx.fillStyle = COLORS.white;
    ctx.shadowColor = accent;
    ctx.shadowBlur = 14;
    ctx.fillText(
      state === "paused" ? "PRESS P OR CLICK TO CONTINUE" : "CLICK, TAP, SPACE, OR ENTER",
      WIDTH / 2,
      panelY + panelHeight - 38
    );

    ctx.restore();
  }

  function drawScreens() {
    if (state === "start") {
      drawOverlay(
        "NEON BREAKER",
        "SHATTER THE GRID. PROTECT THE CORE.",
        COLORS.cyan,
        [
          "Mouse or touch: move the paddle",
          "Keyboard: Arrow keys or A / D",
          "Press P to pause"
        ]
      );
    } else if (state === "gameover") {
      drawOverlay(
        "GAME OVER",
        `FINAL SCORE  ${String(score).padStart(6, "0")}`,
        COLORS.pink,
        [
          `You reached level ${level + 1}`,
          "The neon grid remains unbroken."
        ]
      );
    } else if (state === "victory") {
      drawOverlay(
        "VICTORY",
        `FINAL SCORE  ${String(score).padStart(6, "0")}`,
        COLORS.yellow,
        [
          "All neon sectors have been cleared.",
          lives === 3 ? "Flawless run." : `${lives} ${lives === 1 ? "life" : "lives"} remaining.`
        ]
      );
    } else if (state === "paused") {
      drawOverlay(
        "PAUSED",
        "THE GRID IS STANDING BY",
        COLORS.violet,
        [
          `Score: ${score}`,
          `Level: ${level + 1} of ${MAX_LEVEL}`
        ]
      );
    } else if (state === "levelclear") {
      ctx.save();
      ctx.fillStyle = "rgba(1, 2, 10, 0.48)";
      ctx.fillRect(0, FIELD_TOP, WIDTH, HEIGHT - FIELD_TOP);
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.font = "900 55px system-ui, sans-serif";
      ctx.fillStyle = COLORS.white;
      ctx.shadowColor = COLORS.cyan;
      ctx.shadowBlur = 25;
      ctx.fillText(`LEVEL ${level + 1} CLEAR`, WIDTH / 2, HEIGHT / 2 - 15);
      ctx.font = "700 18px system-ui, sans-serif";
      ctx.fillStyle = COLORS.cyan;
      ctx.fillText(
        level + 1 >= MAX_LEVEL ? "GRID DESTROYED" : "NEXT SECTOR INCOMING",
        WIDTH / 2,
        HEIGHT / 2 + 40
      );
      ctx.restore();
    }
  }

  function drawScanlines() {
    ctx.save();
    ctx.fillStyle = "rgba(0, 0, 0, 0.035)";
    for (let y = 0; y < HEIGHT; y += 4) {
      ctx.fillRect(0, y, WIDTH, 1);
    }

    const vignette = ctx.createRadialGradient(
      WIDTH / 2,
      HEIGHT / 2,
      HEIGHT * 0.22,
      WIDTH / 2,
      HEIGHT / 2,
      WIDTH * 0.7
    );
    vignette.addColorStop(0, "rgba(0, 0, 0, 0)");
    vignette.addColorStop(1, "rgba(0, 0, 0, 0.48)");
    ctx.fillStyle = vignette;
    ctx.fillRect(0, 0, WIDTH, HEIGHT);
    ctx.restore();
  }

  function render(time) {
    ctx.save();

    if (shake > 0.1) {
      ctx.translate(
        (Math.random() - 0.5) * shake,
        (Math.random() - 0.5) * shake
      );
    }

    ctx.clearRect(-20, -20, WIDTH + 40, HEIGHT + 40);
    drawBackground(time);
    drawHUD();
    drawBricks();
    drawParticles();
    drawPaddle();
    drawBall();
    drawReadyPrompt(time);
    drawScreens();
    drawScanlines();

    ctx.restore();
  }

  function frame(time) {
    const dt = Math.min(0.033, Math.max(0, (time - lastTime) / 1000));
    lastTime = time;

    update(dt);
    render(time);
    requestAnimationFrame(frame);
  }

  createStars();
  resizeCanvas();
  buildLevel();
  state = "start";
  requestAnimationFrame(frame);
})();
</script>
