<canvas id="game"></canvas>

<script>
(() => {
  "use strict";

  const canvas = document.getElementById("game");
  const ctx = canvas.getContext("2d", { alpha: false });

  let W = 0;
  let H = 0;
  let DPR = 1;
  let lastTime = 0;
  let elapsed = 0;

  const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
  const rand = (min, max) => min + Math.random() * (max - min);
  const TAU = Math.PI * 2;

  let state = "start";
  let score = 0;
  let lives = 3;
  let level = 1;
  const maxLevel = 5;

  let bricks = [];
  let particles = [];
  let stars = [];

  const keys = {
    left: false,
    right: false
  };

  const paddle = {
    x: 0,
    y: 0,
    w: 130,
    h: 15,
    speed: 850,
    vx: 0,
    prevX: 0,
    targetX: null
  };

  const ball = {
    x: 0,
    y: 0,
    px: 0,
    py: 0,
    r: 8,
    vx: 0,
    vy: 0,
    speed: 430,
    stuck: true
  };

  let audioCtx = null;
  let muted = false;

  const palettes = [
    ["#00e5ff", "#0ea5e9"],
    ["#a78bfa", "#7c3aed"],
    ["#ff4fd8", "#db2777"],
    ["#ffd166", "#f97316"],
    ["#5cff9d", "#22c55e"],
    ["#f472b6", "#be185d"],
    ["#67e8f9", "#0891b2"],
    ["#c4b5fd", "#6d28d9"]
  ];

  function resize() {
    const oldW = W || window.innerWidth;
    const oldH = H || window.innerHeight;

    DPR = Math.max(1, Math.min(2.5, window.devicePixelRatio || 1));
    W = Math.max(320, window.innerWidth);
    H = Math.max(420, window.innerHeight);

    canvas.width = Math.floor(W * DPR);
    canvas.height = Math.floor(H * DPR);
    canvas.style.width = W + "px";
    canvas.style.height = H + "px";

    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);

    const rw = W / oldW;
    const rh = H / oldH;

    paddle.w = clamp(W * 0.16, 86, 168);
    paddle.h = clamp(H * 0.02, 12, 18);
    paddle.y = H - clamp(H * 0.105, 58, 86);
    paddle.speed = clamp(W * 1.15, 650, 1250);

    paddle.x = clamp(paddle.x * rw || (W - paddle.w) / 2, 0, W - paddle.w);
    paddle.targetX = paddle.targetX == null ? null : paddle.targetX * rw;

    ball.r = clamp(Math.min(W, H) * 0.0125, 7, 10);
    ball.x *= rw;
    ball.y *= rh;

    layoutBricks(true);
    if (ball.stuck) setupBallOnPaddle();

    buildStars();
  }

  function buildStars() {
    const count = Math.floor(clamp((W * H) / 9000, 45, 130));
    stars = [];
    for (let i = 0; i < count; i++) {
      stars.push({
        x: Math.random() * W,
        y: Math.random() * H,
        r: rand(0.4, 1.7),
        a: rand(0.15, 0.85),
        twinkle: rand(0.8, 2.8)
      });
    }
  }

  function layoutBricks(preserve) {
    const old = new Map();
    if (preserve) {
      for (const b of bricks) old.set(`${b.row}:${b.col}`, b);
    }

    const cols = 10;
    const rows = Math.min(9, 4 + level);
    const gap = clamp(W * 0.0085, 5, 9);
    const marginX = clamp(W * 0.052, 18, 64);
    const top = clamp(H * 0.145, 76, 116);
    const brickW = (W - marginX * 2 - gap * (cols - 1)) / cols;
    const brickH = clamp(H * 0.036, 18, 27);

    bricks = [];

    for (let row = 0; row < rows; row++) {
      for (let col = 0; col < cols; col++) {
        const saved = old.get(`${row}:${col}`);
        const palette = palettes[row % palettes.length];

        let hp = 1;
        if (level >= 2 && row <= 1) hp++;
        if (level >= 4 && row === 0) hp++;
        if (level >= 5 && (row + col) % 5 === 0) hp++;

        bricks.push({
          row,
          col,
          x: marginX + col * (brickW + gap),
          y: top + row * (brickH + gap),
          w: brickW,
          h: brickH,
          hp: saved ? saved.hp : hp,
          maxHp: saved ? saved.maxHp : hp,
          alive: saved ? saved.alive : true,
          color1: palette[0],
          color2: palette[1],
          pulse: Math.random() * TAU
        });
      }
    }
  }

  function setupBallOnPaddle() {
    ball.stuck = true;
    ball.speed = clamp(365 + level * 36 + Math.min(W, 900) * 0.055, 395, 640);
    ball.x = paddle.x + paddle.w / 2;
    ball.y = paddle.y - ball.r - 3;
    ball.px = ball.x;
    ball.py = ball.y;
    ball.vx = 0;
    ball.vy = 0;
  }

  function launchBall() {
    if (!ball.stuck) return;

    ball.stuck = false;
    const angle = rand(-0.42, 0.42);
    const dir = Math.random() < 0.5 ? -1 : 1;
    ball.vx = Math.sin(angle) * ball.speed + dir * ball.speed * 0.18;
    ball.vy = -Math.abs(Math.cos(angle) * ball.speed);

    normalizeBallSpeed(ball.speed);
    sfx("launch");
  }

  function newGame() {
    score = 0;
    lives = 3;
    level = 1;
    particles = [];
    state = "playing";
    layoutBricks(false);
    setupBallOnPaddle();
    launchBall();
    sfx("start");
  }

  function nextLevel() {
    if (level >= maxLevel) {
      state = "victory";
      ball.stuck = true;
      sfx("win");
      burst(W / 2, H / 2, "#5cff9d", 90, 1.4);
      burst(W / 2, H / 2, "#00e5ff", 70, 1.25);
      return;
    }

    level++;
    layoutBricks(false);
    setupBallOnPaddle();
    burst(W / 2, H * 0.45, "#00e5ff", 60, 1.1);
    sfx("level");
  }

  function loseLife() {
    lives--;
    burst(ball.x, H - 30, "#ff4fd8", 55, 1.15);
    sfx("life");

    if (lives <= 0) {
      state = "gameover";
      ball.stuck = true;
      return;
    }

    setupBallOnPaddle();
  }

  function update(dt) {
    elapsed += dt;
    updateParticles(dt);

    if (state !== "playing") return;

    updatePaddle(dt);

    if (ball.stuck) {
      ball.x = paddle.x + paddle.w / 2;
      ball.y = paddle.y - ball.r - 3;
    } else {
      updateBall(dt);
    }

    if (bricks.length && bricks.every(b => !b.alive)) {
      nextLevel();
    }
  }

  function updatePaddle(dt) {
    paddle.prevX = paddle.x;

    const dir = (keys.right ? 1 : 0) - (keys.left ? 1 : 0);

    if (dir !== 0) {
      paddle.x += dir * paddle.speed * dt;
      paddle.targetX = null;
    } else if (paddle.targetX != null) {
      const desired = paddle.targetX - paddle.w / 2;
      const t = 1 - Math.pow(0.0008, dt);
      paddle.x += (desired - paddle.x) * clamp(t * 16, 0, 1);
    }

    paddle.x = clamp(paddle.x, 0, W - paddle.w);
    paddle.vx = (paddle.x - paddle.prevX) / Math.max(dt, 0.0001);
  }

  function updateBall(dt) {
    ball.px = ball.x;
    ball.py = ball.y;

    ball.x += ball.vx * dt;
    ball.y += ball.vy * dt;

    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
      sfx("wall");
    }

    if (ball.x + ball.r > W) {
      ball.x = W - ball.r;
      ball.vx = -Math.abs(ball.vx);
      sfx("wall");
    }

    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
      sfx("wall");
    }

    if (ball.y - ball.r > H) {
      loseLife();
      return;
    }

    handlePaddleCollision();
    handleBrickCollision();
    enforceGoodBallAngle();
  }

  function handlePaddleCollision() {
    if (ball.vy <= 0) return;
    if (!circleRect(ball, paddle)) return;

    ball.y = paddle.y - ball.r - 0.2;

    const center = paddle.x + paddle.w / 2;
    const relative = clamp((ball.x - center) / (paddle.w / 2), -1, 1);
    const maxAngle = 1.22;
    const angle = relative * maxAngle;

    const speed = clamp(getBallSpeed() * 1.018 + 3, ball.speed, 780);
    ball.vx = Math.sin(angle) * speed + paddle.vx * 0.09;
    ball.vy = -Math.abs(Math.cos(angle) * speed);

    normalizeBallSpeed(speed);
    sfx("paddle");
    spark(ball.x, paddle.y, "#00e5ff", 10);
  }

  function handleBrickCollision() {
    for (const b of bricks) {
      if (!b.alive) continue;
      if (!circleRect(ball, b)) continue;

      reflectFromBrick(b);

      b.hp--;
      score += 10 * level;

      if (b.hp <= 0) {
        b.alive = false;
        score += 40 + level * 12;
        burst(b.x + b.w / 2, b.y + b.h / 2, b.color1, 26, 0.82);
        sfx("brickBreak");
      } else {
        spark(ball.x, ball.y, b.color1, 15);
        sfx("brickHit");
      }

      normalizeBallSpeed(clamp(getBallSpeed() + 1.5, ball.speed, 790));
      break;
    }
  }

  function reflectFromBrick(b) {
    if (ball.py + ball.r <= b.y) {
      ball.y = b.y - ball.r - 0.2;
      ball.vy = -Math.abs(ball.vy);
      return;
    }

    if (ball.py - ball.r >= b.y + b.h) {
      ball.y = b.y + b.h + ball.r + 0.2;
      ball.vy = Math.abs(ball.vy);
      return;
    }

    if (ball.px + ball.r <= b.x) {
      ball.x = b.x - ball.r - 0.2;
      ball.vx = -Math.abs(ball.vx);
      return;
    }

    if (ball.px - ball.r >= b.x + b.w) {
      ball.x = b.x + b.w + ball.r + 0.2;
      ball.vx = Math.abs(ball.vx);
      return;
    }

    const cx = b.x + b.w / 2;
    const cy = b.y + b.h / 2;
    const overlapX = b.w / 2 + ball.r - Math.abs(ball.x - cx);
    const overlapY = b.h / 2 + ball.r - Math.abs(ball.y - cy);

    if (overlapX < overlapY) {
      ball.vx *= -1;
      ball.x += ball.x < cx ? -overlapX : overlapX;
    } else {
      ball.vy *= -1;
      ball.y += ball.y < cy ? -overlapY : overlapY;
    }
  }

  function circleRect(c, r) {
    const closestX = clamp(c.x, r.x, r.x + r.w);
    const closestY = clamp(c.y, r.y, r.y + r.h);
    const dx = c.x - closestX;
    const dy = c.y - closestY;
    return dx * dx + dy * dy <= c.r * c.r;
  }

  function getBallSpeed() {
    return Math.hypot(ball.vx, ball.vy);
  }

  function normalizeBallSpeed(target) {
    const speed = getBallSpeed() || target;
    ball.vx = ball.vx / speed * target;
    ball.vy = ball.vy / speed * target;
