  }

  function burst(x, y, color, count, power) {
    for (let i = 0; i < count; i++) {
      const a = Math.random() * TAU;
      const s = rand(70, 360) * power;
      particles.push({
        x,
        y,
        vx: Math.cos(a) * s,
        vy: Math.sin(a) * s,
        life: rand(0.35, 0.9),
        maxLife: 1,
        size: rand(1.2, 4.2),
        color,
        drag: rand(1.5, 4.5),
        gravity: rand(20, 140)
      });
    }
  }

  function spark(x, y, color, count) {
    for (let i = 0; i < count; i++) {
      const a = Math.random() * TAU;
      const s = rand(40, 220);
      particles.push({
        x,
        y,
        vx: Math.cos(a) * s,
        vy: Math.sin(a) * s,
        life: rand(0.2, 0.55),
        maxLife: 1,
        size: rand(0.8, 2.4),
        color,
        drag: rand(3, 7),
        gravity: rand(0, 70)
      });
    }
  }

  function updateParticles(dt) {
    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i];
      p.life -= dt;
      if (p.life <= 0) {
        particles.splice(i, 1);
        continue;
      }

      const drag = Math.max(0, 1 - p.drag * dt);
      p.vx *= drag;
      p.vy = p.vy * drag + p.gravity * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
    }
  }

  function draw() {
    drawBackground();
    drawBricks();
    drawParticles();
    drawPaddle();
    drawBall();
    drawHUD();

    if (state === "start") {
      drawScreen("NEON BREAKER", "Break every brick. Survive all 5 levels.", "CLICK / TAP / SPACE TO START");
    } else if (state === "gameover") {
      drawScreen("GAME OVER", `Final score: ${score}`, "CLICK / TAP / SPACE TO RETRY");
    } else if (state === "victory") {
      drawScreen("VICTORY", `You cleared all levels. Score: ${score}`, "CLICK / TAP / SPACE TO PLAY AGAIN");
    } else if (state === "playing" && ball.stuck) {
      drawReadyText();
    }
  }

  function drawBackground() {
    ctx.fillStyle = "#030510";
    ctx.fillRect(0, 0, W, H);

    const glow1 = ctx.createRadialGradient(W * 0.18, H * 0.15, 0, W * 0.18, H * 0.15, W * 0.75);
    glow1.addColorStop(0, "rgba(0, 229, 255, 0.16)");
    glow1.addColorStop(0.45, "rgba(124, 58, 237, 0.07)");
    glow1.addColorStop(1, "rgba(0, 0, 0, 0)");
    ctx.fillStyle = glow1;
    ctx.fillRect(0, 0, W, H);

    const glow2 = ctx.createRadialGradient(W * 0.86, H * 0.82, 0, W * 0.86, H * 0.82, W * 0.7);
    glow2.addColorStop(0, "rgba(255, 79, 216, 0.13)");
    glow2.addColorStop(0.5, "rgba(14, 165, 233, 0.05)");
    glow2.addColorStop(1, "rgba(0, 0, 0, 0)");
    ctx.fillStyle = glow2;
    ctx.fillRect(0, 0, W, H);

    ctx.save();
    for (const s of stars) {
      const a = s.a * (0.55 + Math.sin(elapsed * s.twinkle + s.x) * 0.35);
      ctx.globalAlpha = clamp(a, 0.08, 0.9);
      ctx.fillStyle = "#dffbff";
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, TAU);
      ctx.fill();
    }
    ctx.restore();

    ctx.save();
    ctx.globalAlpha = 0.15;
    ctx.strokeStyle = "#00e5ff";
    ctx.lineWidth = 1;

    const grid = 42;
    const offset = (elapsed * 18) % grid;

    for (let x = -grid; x < W + grid; x += grid) {
      ctx.beginPath();
      ctx.moveTo(x, H);
      ctx.lineTo(x + W * 0.18, 0);
      ctx.stroke();
    }

    for (let y = H * 0.58 + offset; y < H + grid; y += grid) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(W, y);
      ctx.stroke();
    }

    ctx.restore();

    ctx.save();
    ctx.globalAlpha = 0.5;
    ctx.strokeStyle = "rgba(0, 229, 255, 0.28)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, H - 1);
    ctx.lineTo(W, H - 1);
    ctx.stroke();
    ctx.restore();
  }

  function drawBricks() {
    ctx.save();

    for (const b of bricks) {
      if (!b.alive) continue;

      const pulse = 0.7 + Math.sin(elapsed * 3 + b.pulse) * 0.18;
      const hpRatio = b.hp / b.maxHp;

      ctx.shadowColor = b.color1;
      ctx.shadowBlur = 12 * pulse;

      const g = ctx.createLinearGradient(b.x, b.y, b.x + b.w, b.y + b.h);
      g.addColorStop(0, b.color1);
      g.addColorStop(1, b.color2);

      roundRect(ctx, b.x, b.y, b.w, b.h, 7);
      ctx.fillStyle = g;
      ctx.globalAlpha = 0.72 + 0.18 * hpRatio;
      ctx.fill();

      ctx.globalAlpha = 1;
      ctx.shadowBlur = 0;
      ctx.strokeStyle = "rgba(255,255,255,0.45)";
      ctx.lineWidth = 1;
      roundRect(ctx, b.x + 0.5, b.y + 0.5, b.w - 1, b.h - 1, 7);
      ctx.stroke();

      if (b.maxHp > 1) {
        ctx.fillStyle = "rgba(0,0,0,0.35)";
        roundRect(ctx, b.x + 6, b.y + b.h - 7, b.w - 12, 3, 2);
        ctx.fill();

        ctx.fillStyle = "#ffffff";
        roundRect(ctx, b.x + 6, b.y + b.h - 7, (b.w - 12) * hpRatio, 3, 2);
        ctx.fill();
      }
    }

    ctx.restore();
  }

  function drawPaddle() {
    ctx.save();

    ctx.shadowColor = "#00e5ff";
    ctx.shadowBlur = 22;

    const g = ctx.createLinearGradient(paddle.x, paddle.y, paddle.x + paddle.w, paddle.y + paddle.h);
    g.addColorStop(0, "#00e5ff");
    g.addColorStop(0.5, "#ffffff");
    g.addColorStop(1, "#ff4fd8");

    roundRect(ctx, paddle.x, paddle.y, paddle.w, paddle.h, paddle.h / 2);
    ctx.fillStyle = g;
    ctx.fill();

    ctx.shadowBlur = 0;
    ctx.globalAlpha = 0.85;
    ctx.fillStyle = "rgba(255,255,255,0.65)";
    roundRect(ctx, paddle.x + paddle.w * 0.16, paddle.y + 3, paddle.w * 0.68, 3, 2);
    ctx.fill();

    ctx.restore();
  }

  function drawBall() {
    ctx.save();

    ctx.shadowColor = "#ffffff";
    ctx.shadowBlur = 18;

    const g = ctx.createRadialGradient(
      ball.x - ball.r * 0.35,
      ball.y - ball.r * 0.4,
      ball.r * 0.1,
      ball.x,
      ball.y,
      ball.r * 1.25
    );

    g.addColorStop(0, "#ffffff");
    g.addColorStop(0.35, "#dffbff");
    g.addColorStop(0.7, "#00e5ff");
    g.addColorStop(1, "#2563eb");

    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.r, 0, TAU);
    ctx.fill();

    ctx.restore();
  }

  function drawParticles() {
    ctx.save();
    ctx.globalCompositeOperation = "lighter";

    for (const p of particles) {
      const alpha = clamp(p.life / 0.9, 0, 1);
      ctx.globalAlpha = alpha;
      ctx.shadowColor = p.color;
      ctx.shadowBlur = 10;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * alpha, 0, TAU);
      ctx.fill();
    }

    ctx.restore();
  }

  function drawHUD() {
    ctx.save();

    const fs = clamp(W * 0.025, 15, 24);
    ctx.font = `700 ${fs}px system-ui, sans-serif`;
    ctx.textBaseline = "top";

    ctx.shadowColor = "#00e5ff";
    ctx.shadowBlur = 10;
    ctx.fillStyle = "#eaffff";

    ctx.textAlign = "left";
    ctx.fillText(`SCORE ${score}`, 18, 16);

    ctx.textAlign = "center";
    ctx.fillText(`LEVEL ${level}/${maxLevel}`, W / 2, 16);

    ctx.textAlign = "right";
    ctx.fillText(`LIVES ${lives}`, W - 18, 16);

    ctx.shadowBlur = 0;
    ctx.globalAlpha = 0.7;
    ctx.font = `500 ${Math.max(11, fs * 0.58)}px system-ui, sans-serif`;
    ctx.fillStyle = "#8eefff";
    ctx.textAlign = "center";
    ctx.fillText("Mouse / Touch / Arrow Keys    Space: Launch    M: Mute", W / 2, 16 + fs + 5);

    ctx.restore();
  }

  function drawReadyText() {
    ctx.save();

    const y = H * 0.56;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";

    ctx.shadowColor = "#ff4fd8";
    ctx.shadowBlur = 18;
    ctx.fillStyle = "#ffffff";
    ctx.font = `800 ${clamp(W * 0.045, 24, 42)}px system-ui, sans-serif`;
    ctx.fillText(`LEVEL ${level}`, W / 2, y - 34);

    ctx.shadowColor = "#00e5ff";
    ctx.font = `700 ${clamp(W * 0.026, 15, 24)}px system-ui, sans-serif`;
    ctx.fillStyle = "#dffbff";
    ctx.fillText("CLICK / TAP / SPACE TO LAUNCH", W / 2, y + 12);

    ctx.restore();
  }

  function drawScreen(title, subtitle, prompt) {
    ctx.save();

    ctx.fillStyle = "rgba(2, 5, 18, 0.72)";
    ctx.fillRect(0, 0, W, H);

    const panelW = Math.min(W - 34, 680);
    const panelH = clamp(H * 0.44, 260, 370);
    const x = (W - panelW) / 2;
    const y = (H - panelH) / 2;

    ctx.shadowColor = "#00e5ff";
    ctx.shadowBlur = 32;
    ctx.fillStyle = "rgba(8, 13, 34, 0.88)";
    roundRect(ctx, x, y, panelW, panelH, 24);
    ctx.fill();

    ctx.shadowBlur = 0;
    const border = ctx.createLinearGradient(x, y, x + panelW, y + panelH);
    border.addColorStop(0, "#00e5ff");
    border.addColorStop(0.5, "#ff4fd8");
    border.addColorStop(1, "#5cff9d");

    ctx.strokeStyle = border;
    ctx.lineWidth = 2;
    roundRect(ctx, x + 1, y + 1, panelW - 2, panelH - 2, 24);
    ctx.stroke();

    ctx.textAlign = "center";
    ctx.textBaseline = "middle";

    ctx.shadowColor = "#ff4fd8";
    ctx.shadowBlur = 20;
    ctx.fillStyle = "#ffffff";
    ctx.font = `900 ${clamp(W * 0.075, 42, 78)}px system-ui, sans-serif`;
    ctx.fillText(title, W / 2, y + panelH * 0.28);

    ctx.shadowColor = "#00e5ff";
    ctx.shadowBlur = 12;
    ctx.fillStyle = "#dffbff";
    ctx.font = `600 ${clamp(W * 0.028, 17, 25)}px system-ui, sans-serif`;
    ctx.fillText(subtitle, W / 2, y + panelH * 0.48);

    const buttonW = Math.min(panelW * 0.72, 430);
    const buttonH = 54;
    const bx = W / 2 - buttonW / 2;
    const by = y + panelH * 0.68;

    ctx.shadowColor = "#00e5ff";
    ctx.shadowBlur = 22;
    const bg = ctx.createLinearGradient(bx, by, bx + buttonW, by);
    bg.addColorStop(0, "rgba(0,229,255,0.95)");
    bg.addColorStop(1, "rgba(255,79,216,0.95)");

    ctx.fillStyle = bg;
    roundRect(ctx, bx, by, buttonW, buttonH, 18);
    ctx.fill();

    ctx.shadowBlur = 0;
    ctx.fillStyle = "#020617";
    ctx.font = `900 ${clamp(W * 0.023, 14, 20)}px system-ui, sans-serif`;
    ctx.fillText(prompt, W / 2, by + buttonH / 2);

    ctx.globalAlpha = 0.75;
    ctx.fillStyle = "#b9f8ff";
    ctx.font = `500 ${clamp(W * 0.019, 12, 16)}px system-ui, sans-serif`;
    ctx.fillText("Angle your paddle hits to steer the ball. Break harder bricks more than once.", W / 2, y + panelH - 36);

    ctx.restore();
  }

  function roundRect(c, x, y, w, h, r) {
    r = Math.min(r, w / 2, h / 2);
    c.beginPath();
    c.moveTo(x + r, y);
    c.arcTo(x + w, y, x + w, y + h, r);
    c.arcTo(x + w, y + h, x, y + h, r);
    c.arcTo(x, y + h, x, y, r);
    c.arcTo(x, y, x + w, y, r);
    c.closePath();
  }

  function initAudio() {
    if (muted) return;
    const AudioClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioClass) return;

    if (!audioCtx) {
      audioCtx = new AudioClass();
    }

    if (audioCtx.state === "suspended") {
      audioCtx.resume();
    }
  }

  function tone(freq, dur, type, gain, when = 0, slideTo = null) {
    if (!audioCtx || muted) return;

    const t = audioCtx.currentTime + when;
    const osc = audioCtx.createOscillator();
    const amp = audioCtx.createGain();

    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slideTo) {
      osc.frequency.exponentialRampToValueAtTime(Math.max(1, slideTo), t + dur);
    }

    amp.gain.setValueAtTime(0.0001, t);
    amp.gain.exponentialRampToValueAtTime(gain, t + 0.008);
    amp.gain.exponentialRampToValueAtTime(0.0001, t + dur);

    osc.connect(amp);
    amp.connect(audioCtx.destination);

    osc.start(t);
    osc.stop(t + dur + 0.03);
  }

  function noiseBurst(dur, gain, when = 0, filterFreq = 1300) {
    if (!audioCtx || muted) return;

    const t = audioCtx.currentTime + when;
    const sr = audioCtx.sampleRate;
    const len = Math.floor(sr * dur);
    const buffer = audioCtx.createBuffer(1, len, sr);
    const data = buffer.getChannelData(0);

    for (let i = 0; i < len; i++) {
      const fade = 1 - i / len;
      data[i] = (Math.random() * 2 - 1) * fade * fade;
    }

    const src = audioCtx.createBufferSource();
    const filter = audioCtx.createBiquadFilter();
    const amp = audioCtx.createGain();

    filter.type = "bandpass";
    filter.frequency.setValueAtTime(filterFreq, t);
    filter.Q.setValueAtTime(2.2, t);

    amp.gain.setValueAtTime(gain, t);
    amp.gain.exponentialRampToValueAtTime(0.0001, t + dur);

    src.buffer = buffer;
    src.connect(filter);
    filter.connect(amp);
    amp.connect(audioCtx.destination);

    src.start(t);
    src.stop(t + dur + 0.02);
  }

  function sfx(name) {
    if (!audioCtx || muted) return;

    switch (name) {
      case "wall":
        tone(220, 0.045, "triangle", 0.025, 0, 170);
        break;
      case "paddle":
        tone(430, 0.055, "square", 0.032, 0, 720);
        break;
      case "launch":
        tone(360, 0.06, "sine", 0.035, 0, 620);
        break;
      case "brickHit":
        tone(520, 0.05, "sawtooth", 0.026, 0, 390);
        break;
      case "brickBreak":
        tone(840, 0.08, "triangle", 0.035, 0, 420);
        noiseBurst(0.08, 0.03, 0, 1800);
        break;
      case "life":
        tone(320, 0.12, "sawtooth", 0.04, 0, 120);
        tone(190, 0.14, "triangle", 0.028, 0.09, 80);
        break;
      case "start":
        tone(440, 0.08, "sine", 0.026, 0);
        tone(660, 0.08, "sine", 0.026, 0.08);
        tone(990, 0.12, "sine", 0.03, 0.16);
        break;
      case "level":
        tone(520, 0.08, "triangle", 0.03, 0);
        tone(780, 0.08, "triangle", 0.03, 0.09);
        tone(1040, 0.11, "triangle", 0.03, 0.18);
        break;
      case "win":
        tone(523.25, 0.12, "sine", 0.035, 0);
        tone(659.25, 0.12, "sine", 0.035, 0.12);
        tone(783.99, 0.12, "sine", 0.035, 0.24);
        tone(1046.5, 0.28, "sine", 0.04, 0.36);
        noiseBurst(0.2, 0.025, 0.32, 2600);
        break;
    }
  }

  function setPointerTarget(e) {
    const rect = canvas.getBoundingClientRect();
    paddle.targetX = clamp(e.clientX - rect.left, 0, W);
  }

  function primaryAction() {
    initAudio();

    if (state === "start" || state === "gameover" || state === "victory") {
      newGame();
      return;
    }

    if (state === "playing" && ball.stuck) {
      launchBall();
    }
  }

  canvas.addEventListener("pointermove", e => {
    e.preventDefault();
    setPointerTarget(e);
  }, { passive: false });

  canvas.addEventListener("pointerdown", e => {
    e.preventDefault();
    canvas.setPointerCapture?.(e.pointerId);
    setPointerTarget(e);
    primaryAction();
  }, { passive: false });

  window.addEventListener("keydown", e => {
    if (e.code === "ArrowLeft" || e.code === "KeyA") {
      keys.left = true;
      e.preventDefault();
    }

    if (e.code === "ArrowRight" || e.code === "KeyD") {
      keys.right = true;
      e.preventDefault();
    }

    if (e.code === "Space" || e.code === "Enter") {
      e.preventDefault();
      primaryAction();
    }

    if (e.code === "KeyM") {
      muted = !muted;
      if (!muted) initAudio();
    }
  });

  window.addEventListener("keyup", e => {
    if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
    if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
  });

  window.addEventListener("resize", resize);

  function loop(now) {
    const t = now / 1000;
    const dt = Math.min(0.033, t - lastTime || 0);
    lastTime = t;

    update(dt);
    draw();

    requestAnimationFrame(loop);
  }

  resize();
  layoutBricks(false);
  setupBallOnPaddle();
  state = "start";
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
