    align-items: center;
    justify-content: center;
    background: radial-gradient(ellipse at 50% 30%, #120530 0%, #05010f 70%);
  }

  #gameCanvas {
    display: block;
    box-shadow: 0 0 40px rgba(0, 255, 255, 0.15), 0 0 80px rgba(255, 0, 255, 0.08);
