<body>
    <div id="game-container">
        <canvas id="gameCanvas"></canvas>
    </div>

    <script>
        (function() {
            const canvas = document.getElementById('gameCanvas');
            const ctx = canvas.getContext('2d');

            // --- Canvas dimensions (logical) ---
            const W = 480;
            const H = 640;
            canvas.width = W;
            canvas.height = H;

            // --- Audio Engine ---
            const AudioCtx = window.AudioContext || window.webkitAudioContext;
            let audioCtx = null;

            function initAudio() {
                if (!audioCtx) {
                    audioCtx = new AudioCtx();
                }
                if (audioCtx.state === 'suspended') {
                    audioCtx.resume();
                }
            }

            function playSound(freq, type, duration, volume = 0.15, decay = true, detune = 0) {
                if (!audioCtx) return;
                try {
                    const t = audioCtx.currentTime;
                    const osc = audioCtx.createOscillator();
                    const gain = audioCtx.createGain();
                    osc.type = type;
                    osc.frequency.setValueAtTime(freq, t);
                    if (detune) osc.detune.setValueAtTime(detune, t);
                    gain.gain.setValueAtTime(volume, t);
                    if (decay) {
                        gain.gain.exponentialRampToValueAtTime(0.001, t + duration);
                    } else {
                        gain.gain.setValueAtTime(volume, t);
                        gain.gain.setValueAtTime(0, t + duration);
                    }
                    osc.connect(gain);
                    gain.connect(audioCtx.destination);
                    osc.start(t);
                    osc.stop(t + duration);
                } catch (e) {
                    // Silently fail
                }
            }

            function sfxBrickHit() {
                playSound(600 + Math.random() * 400, 'square', 0.08, 0.12, true, Math.random() * 30);
            }

            function sfxPaddleHit() {
                playSound(200, 'triangle', 0.1, 0.15, true, 0);
                playSound(300, 'sine', 0.06, 0.1, true, 10);
            }

            function sfxWallHit() {
                playSound(120, 'sine', 0.08, 0.1, true, -5);
            }

            function sfxLifeLost() {
                playSound(80, 'sawtooth', 0.3, 0.5, true, -20);
                playSound(60, 'square', 0.2, 0.4, true, -30);
            }

            function sfxLevelUp() {
                playSound(440, 'sine', 0.1, 0.2, false, 0);
                setTimeout(() => playSound(554, 'sine', 0.1, 0.2, false, 0), 150);
                setTimeout(() => playSound(660, 'sine', 0.1, 0.3, false, 0), 300);
            }

            function sfxGameOver() {
                playSound(200, 'sawtooth', 0.25, 0.6, true, -10);
                setTimeout(() => playSound(150, 'sawtooth', 0.25, 0.6, true, -15), 300);
                setTimeout(() => playSound(100, 'sawtooth', 0.3, 0.8, true, -20), 600);
            }

            function sfxVictory() {
                const notes = [523, 659, 784, 1047];
                notes.forEach((f, i) => {
                    setTimeout(() => playSound(f, 'sine', 0.15, 0.35, false, 0), i * 120);
                });
            }

            // --- Game State ---
            const STATE = {
                START: 'start',
                PLAYING: 'playing',
                GAME_OVER: 'gameOver',
                VICTORY: 'victory',
                LEVEL_TRANSITION: 'levelTransition',
            };

            let gameState = STATE.START;
            let score = 0;
            let lives = 3;
            let level = 1;
            let comboCount = 0;
            let comboTimer = 0;
            let shakeAmount = 0;
            let levelTransitionTimer = 0;

            // --- Paddle ---
            const paddle = {
                x: W / 2,
                y: H - 55,
                w: 90,
                h: 14,
                speed: 0,
                targetX: W / 2,
                baseW: 90,
                glowIntensity: 0,
            };

            // --- Ball ---
            const ball = {
                x: W / 2,
                y: H - 75,
                r: 7,
                dx: 0,
                dy: 0,
                speed: 5.5,
                baseSpeed: 5.5,
                attached: true,
                trail: [],
                maxTrail: 12,
            };

            // --- Bricks ---
            let bricks = [];
            const BRICK_ROWS = 6;
            const BRICK_COLS = 8;
            const BRICK_W = 50;
            const BRICK_H = 20;
            const BRICK_PAD = 4;
            const BRICK_OFFSET_X = (W - BRICK_COLS * (BRICK_W + BRICK_PAD) + BRICK_PAD) / 2;
            const BRICK_OFFSET_Y = 70;

            // --- Particles ---
            let particles = [];

            // --- Power-ups ---
            let powerUps = [];
            let activePowerUp = null;
            let powerUpTimer = 0;
            const POWERUP_TYPES = ['widen', 'slow', 'multiball', 'extralife'];
            const POWERUP_COLORS = {
                widen: '#ff00e5',
                slow: '#39ff14',
                multiball: '#ffe600',
                extralife: '#ff6b35',
            };

            // --- Multi-ball ---
            let extraBalls = [];

            // --- Input ---
            let mouseX = W / 2;
            let keys = {};
            let touchActive = false;
            let touchX = W / 2;

            function resetBall(attach = true) {
                ball.x = paddle.x;
                ball.y = paddle.y - paddle.h / 2 - ball.r - 2;
                ball.dx = 0;
                ball.dy = 0;
                ball.speed = ball.baseSpeed;
                ball.attached = attach;
                ball.trail = [];
            }

            function launchBall() {
                if (!ball.attached) return;
                ball.attached = false;
                const angle = -Math.PI / 2 + (Math.random() - 0.5) * 0.8;
                ball.dx = Math.cos(angle) * ball.speed;
                ball.dy = Math.sin(angle) * ball.speed;
                if (Math.abs(ball.dx) < 1.5) ball.dx = (ball.dx >= 0 ? 1 : -1) * 2.5;
                if (ball.dy > -2) ball.dy = -ball.speed * 0.8;
            }

            function generateBricks() {
                bricks = [];
                const colors = ['#ff00e5', '#ff6b35', '#ffe600', '#39ff14', '#00f0ff', '#4d4dff'];
                const points = [60, 50, 40, 30, 20, 10];

                for (let row = 0; row < BRICK_ROWS; row++) {
                    for (let col = 0; col < BRICK_COLS; col++) {
                        const hp = row < 2 ? 2 : 1;
                        bricks.push({
                            x: BRICK_OFFSET_X + col * (BRICK_W + BRICK_PAD),
                            y: BRICK_OFFSET_Y + row * (BRICK_H + BRICK_PAD),
                            w: BRICK_W,
                            h: BRICK_H,
                            alive: true,
                            hp: hp,
                            maxHp: hp,
                            color: colors[row],
                            points: points[row],
                            glowPhase: Math.random() * Math.PI * 2,
                        });
                    }
                }
            }

            function spawnParticles(x, y, color, count = 15) {
                for (let i = 0; i < count; i++) {
                    const angle = Math.random() * Math.PI * 2;
                    const speed = 1.5 + Math.random() * 5;
                    particles.push({
                        x: x,
                        y: y,
                        vx: Math.cos(angle) * speed,
                        vy: Math.sin(angle) * speed,
                        life: 1,
                        decay: 0.015 + Math.random() * 0.04,
                        size: 1.5 + Math.random() * 3.5,
                        color: color,
                    });
                }
            }

            function spawnPowerUp(x, y) {
                if (Math.random() < 0.18) {
                    const type = POWERUP_TYPES[Math.floor(Math.random() * POWERUP_TYPES.length)];
                    powerUps.push({
                        x: x,
                        y: y,
                        w: 22,
                        h: 22,
                        type: type,
                        vy: 1.8 + Math.random() * 1.2,
                        glow: 0,
                    });
                }
            }

            function applyPowerUp(type) {
                if (activePowerUp) {
                    // Remove previous power-up effects
                    paddle.w = paddle.baseW;
                    ball.speed = ball.baseSpeed;
                    for (const eb of extraBalls) eb.alive = false;
                    extraBalls = [];
                }
                activePowerUp = type;
                powerUpTimer = 480; // ~8 seconds at 60fps

                switch (type) {
                    case 'widen':
                        paddle.w = paddle.baseW * 1.6;
                        paddle.glowIntensity = 1;
                        playSound(500, 'sine', 0.08, 0.2, false, 0);
                        break;
                    case 'slow':
                        ball.speed = ball.baseSpeed * 0.55;
                        for (const eb of extraBalls) eb.speed = ball.baseSpeed * 0.55;
                        playSound(350, 'sine', 0.08, 0.2, false, 0);
                        break;
                    case 'multiball':
                        for (let i = 0; i < 2; i++) {
                            extraBalls.push({
                                x: ball.x,
                                y: ball.y,
                                r: ball.r,
                                dx: (Math.random() - 0.5) * ball.speed * 1.5,
                                dy: -ball.speed * 0.7 - Math.random() * 2,
                                speed: ball.speed,
                                alive: true,
                                trail: [],
                            });
                        }
                        playSound(600, 'sine', 0.1, 0.25, false, 0);
                        break;
                    case 'extralife':
                        lives = Math.min(lives + 1, 5);
                        playSound(800, 'sine', 0.12, 0.3, false, 0);
                        activePowerUp = null;
                        powerUpTimer = 0;
                        break;
                }
            }

            function updatePowerUpTimer() {
                if (powerUpTimer > 0) {
                    powerUpTimer--;
                    if (powerUpTimer <= 0) {
                        // Expire power-up
                        paddle.w = paddle.baseW;
                        ball.speed = ball.baseSpeed;
                        for (const eb of extraBalls) eb.alive = false;
                        extraBalls = [];
                        activePowerUp = null;
                        paddle.glowIntensity = Math.max(0, paddle.glowIntensity - 0.5);
                    }
                }
                if (paddle.glowIntensity > 0 && activePowerUp !== 'widen') {
                    paddle.glowIntensity = Math.max(0, paddle.glowIntensity - 0.03);
                }
            }

            function handleBallBrickCollision(b, isExtra = false) {
                for (const brick of bricks) {
                    if (!brick.alive) continue;
                    const bx = b.x;
                    const by = b.y;
                    const br = b.r;

                    // AABB vs circle
                    const closestX = Math.max(brick.x, Math.min(bx, brick.x + brick.w));
                    const closestY = Math.max(brick.y, Math.min(by, brick.y + brick.h));
                    const distX = bx - closestX;
                    const distY = by - closestY;
                    const dist = Math.sqrt(distX * distX + distY * distY);

                    if (dist < br) {
                        // Collision
                        brick.hp--;
                        if (brick.hp <= 0) {
                            brick.alive = false;
                            score += brick.points * (1 + Math.floor(comboCount / 5));
                            comboCount++;
                            comboTimer = 90;
                            spawnParticles(brick.x + brick.w / 2, brick.y + brick.h / 2, brick.color, 20);
                            spawnPowerUp(brick.x + brick.w / 2, brick.y + brick.h / 2);
                            sfxBrickHit();
                            shakeAmount = Math.max(shakeAmount, 3);
                        } else {
                            spawnParticles(brick.x + brick.w / 2, brick.y + brick.h / 2, brick.color, 8);
                            sfxBrickHit();
                            shakeAmount = Math.max(shakeAmount, 1.5);
                            brick.glowPhase += 0.5;
                        }

                        // Reflect ball
                        const overlap = br - dist;
                        const nx = distX / (dist || 1);
                        const ny = distY / (dist || 1);
                        b.x += nx * overlap;
                        b.y += ny * overlap;

                        // Determine which side was hit
                        const brickCX = brick.x + brick.w / 2;
                        const brickCY = brick.y + brick.h / 2;
                        const relX = b.x - brickCX;
                        const relY = b.y - brickCY;
                        const hw = brick.w / 2;
                        const hh = brick.h / 2;

                        if (Math.abs(relX) / hw > Math.abs(relY) / hh) {
                            b.dx = Math.abs(b.dx) * (relX > 0 ? 1 : -1);
                        } else {
                            b.dy = Math.abs(b.dy) * (relY > 0 ? 1 : -1);
                        }
                        // Normalize speed
                        const spd = Math.sqrt(b.dx * b.dx + b.dy * b.dy);
                        if (spd > 0) {
                            b.dx = (b.dx / spd) * b.speed;
                            b.dy = (b.dy / spd) * b.speed;
                        }
                        return true;
                    }
                }
                return false;
            }

            function checkAllBricksCleared() {
                return bricks.every(b => !b.alive);
            }

            function nextLevel() {
                level++;
                ball.baseSpeed = ball.baseSpeed + 0.6;
                ball.speed = ball.baseSpeed;
                paddle.baseW = Math.max(55, paddle.baseW - 3);
                paddle.w = paddle.baseW;
                activePowerUp = null;
                powerUpTimer = 0;
                powerUps = [];
                extraBalls = [];
                paddle.glowIntensity = 0;
                generateBricks();
                resetBall(true);
                ball.x = paddle.x;
                ball.y = paddle.y - paddle.h / 2 - ball.r - 2;
                gameState = STATE.LEVEL_TRANSITION;
                levelTransitionTimer = 120;
                sfxLevelUp();
            }

            function loseLife() {
                lives--;
                comboCount = 0;
                comboTimer = 0;
                activePowerUp = null;
                powerUpTimer = 0;
                powerUps = [];
                extraBalls = [];
                paddle.w = paddle.baseW;
                paddle.glowIntensity = 0;
                ball.speed = ball.baseSpeed;
                sfxLifeLost();
                shakeAmount = 8;

                if (lives <= 0) {
                    gameState = STATE.GAME_OVER;
                    sfxGameOver();
                } else {
                    resetBall(true);
                    ball.x = paddle.x;
                    ball.y = paddle.y - paddle.h / 2 - ball.r - 2;
                }
            }

            function resetGame() {
                score = 0;
                lives = 3;
                level = 1;
                comboCount = 0;
                comboTimer = 0;
                ball.baseSpeed = 5.5;
                ball.speed = ball.baseSpeed;
                paddle.baseW = 90;
                paddle.w = paddle.baseW;
                paddle.glowIntensity = 0;
                activePowerUp = null;
                powerUpTimer = 0;
                powerUps = [];
                extraBalls = [];
                particles = [];
                shakeAmount = 0;
                generateBricks();
                resetBall(true);
                ball.x = paddle.x;
                ball.y = paddle.y - paddle.h / 2 - ball.r - 2;
                gameState = STATE.PLAYING;
            }

            // --- Initialize ---
            generateBricks();
            resetBall(true);
            ball.x = paddle.x;
            ball.y = paddle.y - paddle.h / 2 - ball.r - 2;

            // --- Event Listeners ---
            canvas.addEventListener('mousemove', (e) => {
                const rect = canvas.getBoundingClientRect();
                const scaleX = W / rect.width;
                mouseX = (e.clientX - rect.left) * scaleX;
                mouseX = Math.max(paddle.w / 2, Math.min(W - paddle.w / 2, mouseX));
                if (!touchActive) {
                    paddle.targetX = mouseX;
                }
            });

            canvas.addEventListener('click', (e) => {
                initAudio();
                if (gameState === STATE.START) {
                    resetGame();
                    gameState = STATE.PLAYING;
                } else if (gameState === STATE.GAME_OVER || gameState === STATE.VICTORY) {
                    resetGame();
                } else if (gameState === STATE.PLAYING && ball.attached) {
                    launchBall();
                }
            });

            canvas.addEventListener('touchstart', (e) => {
                e.preventDefault();
                initAudio();
                touchActive = true;
                const rect = canvas.getBoundingClientRect();
                const scaleX = W / rect.width;
                touchX = (e.touches[0].clientX - rect.left) * scaleX;
                touchX = Math.max(paddle.w / 2, Math.min(W - paddle.w / 2, touchX));
                paddle.targetX = touchX;

                if (gameState === STATE.START) {
                    resetGame();
                    gameState = STATE.PLAYING;
                } else if (gameState === STATE.GAME_OVER || gameState === STATE.VICTORY) {
                    resetGame();
                } else if (gameState === STATE.PLAYING && ball.attached) {
                    launchBall();
                }
            }, { passive: false });

            canvas.addEventListener('touchmove', (e) => {
                e.preventDefault();
                const rect = canvas.getBoundingClientRect();
                const scaleX = W / rect.width;
                touchX = (e.touches[0].clientX - rect.left) * scaleX;
                touchX = Math.max(paddle.w / 2, Math.min(W - paddle.w / 2, touchX));
                paddle.targetX = touchX;
            }, { passive: false });

            canvas.addEventListener('touchend', (e) => {
                e.preventDefault();
                touchActive = false;
            }, { passive: false });

            document.addEventListener('keydown', (e) => {
                keys[e.key] = true;
                initAudio();
                if (e.key === ' ' || e.key === 'Spacebar') {
                    e.preventDefault();
                    if (gameState === STATE.START) {
                        resetGame();
                        gameState = STATE.PLAYING;
                    } else if (gameState === STATE.GAME_OVER || gameState === STATE.VICTORY) {
                        resetGame();
                    } else if (gameState === STATE.PLAYING && ball.attached) {
                        launchBall();
                    }
                }
                if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
                    e.preventDefault();
                }
            });

            document.addEventListener('keyup', (e) => {
                keys[e.key] = false;
            });

            // --- Update ---
            function update() {
                if (gameState === STATE.LEVEL_TRANSITION) {
                    levelTransitionTimer--;
                    if (levelTransitionTimer <= 0) {
                        gameState = STATE.PLAYING;
                    }
                    // Still update particles
                    for (let i = particles.length - 1; i >= 0; i--) {
                        const p = particles[i];
                        p.x += p.vx;
                        p.y += p.vy;
                        p.life -= p.decay;
                        if (p.life <= 0) particles.splice(i, 1);
                    }
                    updatePowerUpTimer();
                    return;
                }

                if (gameState !== STATE.PLAYING) {
                    // Still update particles for visual flair on game over / victory
                    for (let i = particles.length - 1; i >= 0; i--) {
                        const p = particles[i];
                        p.x += p.vx;
                        p.y += p.vy;
                        p.life -= p.decay;
                        if (p.life <= 0) particles.splice(i, 1);
                    }
                    return;
                }

                // --- Paddle movement ---
                if (!touchActive) {
                    if (keys['ArrowLeft'] || keys['a'] || keys['A']) {
                        paddle.targetX -= 8;
                    }
                    if (keys['ArrowRight'] || keys['d'] || keys['D']) {
                        paddle.targetX += 8;
                    }
                    if (!keys['ArrowLeft'] && !keys['a'] && !keys['A'] &&
                        !keys['ArrowRight'] && !keys['d'] && !keys['D']) {
                        paddle.targetX = mouseX;
                    }
                }
                paddle.targetX = Math.max(paddle.w / 2, Math.min(W - paddle.w / 2, paddle.targetX));
                paddle.x += (paddle.targetX - paddle.x) * 0.35;
                paddle.speed = (paddle.targetX - paddle.x) * 0.35;

                // --- Attached ball follows paddle ---
                if (ball.attached) {
                    ball.x = paddle.x;
                    ball.y = paddle.y - paddle.h / 2 - ball.r - 2;
                    ball.trail = [];
                }

                // --- Update ball ---
                if (!ball.attached) {
                    ball.trail.push({ x: ball.x, y: ball.y, life: 1 });
                    if (ball.trail.length > ball.maxTrail) ball.trail.shift();
                    for (const t of ball.trail) t.life -= 0.06;

                    ball.x += ball.dx;
                    ball.y += ball.dy;

                    // Wall collisions
                    if (ball.x - ball.r <= 0) {
                        ball.x = ball.r;
                        ball.dx = Math.abs(ball.dx);
                        sfxWallHit();
                        spawnParticles(ball.x, ball.y, '#00f0ff', 6);
                    }
                    if (ball.x + ball.r >= W) {
                        ball.x = W - ball.r;
                        ball.dx = -Math.abs(ball.dx);
                        sfxWallHit();
                        spawnParticles(ball.x, ball.y, '#00f0ff', 6);
                    }
                    if (ball.y - ball.r <= 0) {
                        ball.y = ball.r;
                        ball.dy = Math.abs(ball.dy);
                        sfxWallHit();
                        spawnParticles(ball.x, ball.y, '#00f0ff', 6);
                    }

                    // Bottom death
                    if (ball.y + ball.r > H + 20) {
                        loseLife();
                        return;
                    }

                    // Paddle collision
                    if (ball.dy > 0 &&
                        ball.y + ball.r >= paddle.y - paddle.h / 2 &&
                        ball.y - ball.r <= paddle.y + paddle.h / 2 &&
                        ball.x + ball.r >= paddle.x - paddle.w / 2 &&
                        ball.x - ball.r <= paddle.x + paddle.w / 2) {

                        ball.y = paddle.y - paddle.h / 2 - ball.r;
                        const hitPos = (ball.x - paddle.x) / (paddle.w / 2);
                        const maxAngle = Math.PI / 3;
                        const angle = hitPos * maxAngle;
                        const spd = Math.sqrt(ball.dx * ball.dx + ball.dy * ball.dy);
                        ball.dx = Math.sin(angle) * ball.speed;
                        ball.dy = -Math.cos(angle) * ball.speed;
                        const newSpd = Math.sqrt(ball.dx * ball.dx + ball.dy * ball.dy);
                        if (newSpd > 0) {
                            ball.dx = (ball.dx / newSpd) * ball.speed;
                            ball.dy = (ball.dy / newSpd) * ball.speed;
                        }
                        if (Math.abs(ball.dy) < 2) ball.dy = -ball.speed * 0.7;
                        sfxPaddleHit();
                        spawnParticles(ball.x, ball.y, '#ffffff', 8);
                        comboCount = 0;
                        comboTimer = 0;
                    }

                    // Brick collision
                    handleBallBrickCollision(ball, false);
                }

                // --- Update extra balls ---
                for (const eb of extraBalls) {
                    if (!eb.alive) continue;
                    eb.trail.push({ x: eb.x, y: eb.y, life: 1 });
                    if (eb.trail.length > 8) eb.trail.shift();
                    for (const t of eb.trail) t.life -= 0.07;

                    eb.x += eb.dx;
                    eb.y += eb.dy;

                    if (eb.x - eb.r <= 0) { eb.x = eb.r;
                        eb.dx = Math.abs(eb.dx); }
                    if (eb.x + eb.r >= W) { eb.x = W - eb.r;
                        eb.dx = -Math.abs(eb.dx); }
                    if (eb.y - eb.r <= 0) { eb.y = eb.r;
                        eb.dy = Math.abs(eb.dy); }
                    if (eb.y + eb.r > H + 20) { eb.alive = false; continue; }

                    if (eb.dy > 0 &&
                        eb.y + eb.r >= paddle.y - paddle.h / 2 &&
                        eb.y - eb.r <= paddle.y + paddle.h / 2 &&
                        eb.x + eb.r >= paddle.x - paddle.w / 2 &&
                        eb.x - eb.r <= paddle.x + paddle.w / 2) {
                        eb.y = paddle.y - paddle.h / 2 - eb.r;
                        const hitPos = (eb.x - paddle.x) / (paddle.w / 2);
                        const maxAngle = Math.PI / 3;
                        const angle = hitPos * maxAngle;
                        eb.dx = Math.sin(angle) * eb.speed;
                        eb.dy = -Math.cos(angle) * eb.speed;
                        const nspd = Math.sqrt(eb.dx * eb.dx + eb.dy * eb.dy);
                        if (nspd > 0) { eb.dx = (eb.dx / nspd) * eb.speed;
                            eb.dy = (eb.dy / nspd) * eb.speed; }
                        if (Math.abs(eb.dy) < 2) eb.dy = -eb.speed * 0.7;
                        sfxPaddleHit();
                    }
                    handleBallBrickCollision(eb, true);
                }
                extraBalls = extraBalls.filter(eb => eb.alive);

                // --- Update power-ups ---
                for (const pu of powerUps) {
                    pu.y += pu.vy;
                    pu.glow += 0.06;
                    if (pu.y > H + 30) {
                        pu.collected = true;
                    }
                    // Check paddle collision
                    if (!pu.collected &&
                        pu.y + pu.h / 2 >= paddle.y - paddle.h / 2 &&
                        pu.y - pu.h / 2 <= paddle.y + paddle.h / 2 &&
                        pu.x + pu.w / 2 >= paddle.x - paddle.w / 2 &&
                        pu.x - pu.w / 2 <= paddle.x + paddle.w / 2) {
                        applyPowerUp(pu.type);
                        pu.collected = true;
                        spawnParticles(pu.x, pu.y, POWERUP_COLORS[pu.type], 12);
                    }
                }
                powerUps = powerUps.filter(pu => !pu.collected);

                // --- Update particles ---
                for (let i = particles.length - 1; i >= 0; i--) {
                    const p = particles[i];
                    p.x += p.vx;
                    p.y += p.vy;
                    p.life -= p.decay;
                    if (p.life <= 0) particles.splice(i, 1);
                }

                // --- Combo timer ---
                if (comboTimer > 0) {
                    comboTimer--;
                    if (comboTimer <= 0) comboCount = 0;
                }

                // --- Shake decay ---
                shakeAmount *= 0.85;
                if (shakeAmount < 0.1) shakeAmount = 0;

                // --- Power-up timer ---
                updatePowerUpTimer();

                // --- Check victory ---
                if (checkAllBricksCleared()) {
                    nextLevel();
                }
            }

            // --- Draw ---
            function drawBackground() {
                // Dark bg with subtle grid
                ctx.fillStyle = '#080816';
                ctx.fillRect(0, 0, W, H);

                ctx.strokeStyle = 'rgba(0, 240, 255, 0.04)';
                ctx.lineWidth = 0.5;
                const gridSize = 30;
                for (let x = gridSize; x < W; x += gridSize) {
                    ctx.beginPath();
                    ctx.moveTo(x, 0);
                    ctx.lineTo(x, H);
                    ctx.stroke();
                }
                for (let y = gridSize; y < H; y += gridSize) {
                    ctx.beginPath();
                    ctx.moveTo(0, y);
                    ctx.lineTo(W, y);
                    ctx.stroke();
                }
            }

            function drawBricks() {
                const time = performance.now() / 1000;
                for (const brick of bricks) {
                    if (!brick.alive) continue;
                    const alpha = brick.hp / brick.maxHp;
                    const glow = 0.5 + 0.5 * Math.sin(time * 3 + brick.glowPhase);

                    // Brick body
                    const grad = ctx.createLinearGradient(brick.x, brick.y, brick.x, brick.y + brick.h);
                    grad.addColorStop(0, brick.color);
                    grad.addColorStop(1, 'rgba(0,0,0,0.6)');
                    ctx.fillStyle = grad;
                    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);

                    // Inner highlight
                    ctx.fillStyle = `rgba(255,255,255,${0.15 * alpha})`;
                    ctx.fillRect(brick.x + 2, brick.y + 2, brick.w - 4, brick.h / 2 - 2);

                    // Glow border
                    ctx.strokeStyle = brick.color;
                    ctx.lineWidth = 1.5;
                    ctx.shadowColor = brick.color;
                    ctx.shadowBlur = 6 + glow * 8;
                    ctx.strokeRect(brick.x, brick.y, brick.w, brick.h);
                    ctx.shadowBlur = 0;

                    // If damaged, draw crack lines
                    if (brick.hp < brick.maxHp) {
                        ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                        ctx.lineWidth = 1;
                        ctx.beginPath();
                        ctx.moveTo(brick.x + brick.w * 0.3, brick.y);
                        ctx.lineTo(brick.x + brick.w * 0.5, brick.y + brick.h * 0.5);
                        ctx.lineTo(brick.x + brick.w * 0.7, brick.y + brick.h);
                        ctx.stroke();
                    }
                }
            }

            function drawPaddle() {
                const glowColor = activePowerUp === 'widen' ? '#ff00e5' : '#00f0ff';
                const glowBlur = 12 + paddle.glowIntensity * 18;

                ctx.save();
                // Glow
                ctx.shadowColor = glowColor;
                ctx.shadowBlur = glowBlur;

                const grad = ctx.createLinearGradient(paddle.x - paddle.w / 2, paddle.y,
                    paddle.x + paddle.w / 2, paddle.y);
                grad.addColorStop(0, '#00f0ff');
                grad.addColorStop(0.5, '#ffffff');
                grad.addColorStop(1, '#00f0ff');
                ctx.fillStyle = grad;

                const rx = paddle.h / 2;
                const py = paddle.y - paddle.h / 2;
                ctx.beginPath();
                ctx.moveTo(paddle.x - paddle.w / 2 + rx, py);
                ctx.lineTo(paddle.x + paddle.w / 2 - rx, py);
                ctx.arcTo(paddle.x + paddle.w / 2, py, paddle.x + paddle.w / 2, py + rx, rx);
                ctx.lineTo(paddle.x + paddle.w / 2, py + paddle.h - rx);
                ctx.arcTo(paddle.x + paddle.w / 2, py + paddle.h, paddle.x + paddle.w / 2 - rx, py + paddle.h,
                rx);
                ctx.lineTo(paddle.x - paddle.w / 2 + rx, py + paddle.h);
                ctx.arcTo(paddle.x - paddle.w / 2, py + paddle.h, paddle.x - paddle.w / 2, py + paddle.h - rx, rx);
                ctx.lineTo(paddle.x - paddle.w / 2, py + rx);
                ctx.arcTo(paddle.x - paddle.w / 2, py, paddle.x - paddle.w / 2 + rx, py, rx);
                ctx.closePath();
                ctx.fill();

                ctx.shadowBlur = 0;
                ctx.restore();

                // Bright top edge
                ctx.strokeStyle = 'rgba(255,255,255,0.7)';
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(paddle.x - paddle.w / 2 + rx, py + 1);
                ctx.lineTo(paddle.x + paddle.w / 2 - rx, py + 1);
                ctx.stroke();
            }

            function drawBall(b, isExtra = false) {
                if (!b || (isExtra && !b.alive)) return;
                const alpha = isExtra ? 0.7 : 1;

                // Trail
                if (b.trail && b.trail.length > 1) {
                    for (let i = 1; i < b.trail.length; i++) {
                        const t = b.trail[i];
                        const prev = b.trail[i - 1];
                        if (t.life <= 0) continue;
                        ctx.strokeStyle = `rgba(0,240,255,${t.life * 0.5 * alpha})`;
                        ctx.lineWidth = b.r * t.life;
                        ctx.beginPath();
                        ctx.moveTo(prev.x, prev.y);
                        ctx.lineTo(t.x, t.y);
                        ctx.stroke();
                    }
                }

                // Ball glow
                ctx.save();
                ctx.shadowColor = isExtra ? '#ffe600' : '#00f0ff';
                ctx.shadowBlur = 14;

                const grad = ctx.createRadialGradient(b.x - b.r * 0.3, b.y - b.r * 0.3, b.r * 0.1, b.x, b.y, b.r);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.4, isExtra ? '#ffe600' : '#00f0ff');
                grad.addColorStop(1, 'rgba(0,100,150,0.3)');
                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
                ctx.fill();
                ctx.shadowBlur = 0;
                ctx.restore();
            }

            function drawParticles() {
                for (const p of particles) {
                    const alpha = p.life;
                    ctx.fillStyle = p.color.replace(')', `, ${alpha})`).replace('rgb',
                        'rgba');
                    if (p.color.startsWith('#')) {
                        ctx.fillStyle = p.color;
                        ctx.globalAlpha = alpha;
                    }
                    ctx.beginPath();
                    ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
                    ctx.fill();
                }
                ctx.globalAlpha = 1;
            }

            function drawPowerUps() {
                const time = performance.now() / 1000;
                for (const pu of powerUps) {
                    const color = POWERUP_COLORS[pu.type];
                    const pulse = 1 + Math.sin(time * 5 + pu.glow) * 0.2;

                    ctx.save();
                    ctx.shadowColor = color;
                    ctx.shadowBlur = 10 + Math.sin(time * 4) * 5;
                    ctx.fillStyle = color;
                    ctx.beginPath();
                    const cx = pu.x;
                    const cy = pu.y;
                    const s = pu.w / 2 * pulse;
                    // Diamond shape
                    ctx.moveTo(cx, cy - s);
                    ctx.lineTo(cx + s, cy);
                    ctx.lineTo(cx, cy + s);
                    ctx.lineTo(cx - s, cy);
                    ctx.closePath();
                    ctx.fill();
                    ctx.shadowBlur = 0;

                    // Icon letter
                    ctx.fillStyle = '#fff';
                    ctx.font = 'bold 11px "Courier New", monospace';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    const icon = pu.type === 'widen' ? 'W' : pu.type === 'slow' ? 'S' : pu.type === 'multiball' ?
                        'M' : '♥';
                    ctx.fillText(icon, cx, cy);
                    ctx.restore();
                }
            }

            function drawHUD() {
                // Score
                ctx.fillStyle = '#00f0ff';
                ctx.font = 'bold 16px "Courier New", monospace';
                ctx.textAlign = 'left';
                ctx.fillText(`SCORE: ${score}`, 15, 30);

                // Level
                ctx.textAlign = 'center';
                ctx.fillText(`LEVEL ${level}`, W / 2, 30);

                // Lives
                ctx.textAlign = 'right';
                ctx.fillStyle = '#ff00e5';
                let livesStr = '';
                for (let i = 0; i < lives; i++) livesStr += '♥ ';
                ctx.fillText(`LIVES: ${livesStr.trim()}`, W - 15, 30);

                // Combo
                if (comboCount > 1 && comboTimer > 0) {
                    const comboAlpha = Math.min(1, comboTimer / 30);
                    ctx.fillStyle = `rgba(255, 230, 0, ${comboAlpha})`;
                    ctx.textAlign = 'center';
                    ctx.font = 'bold 20px "Courier New", monospace';
                    ctx.fillText(`COMBO x${comboCount}`, W / 2, 55);
                }

                // Active power-up indicator
                if (activePowerUp && powerUpTimer > 0) {
                    const secLeft = Math.ceil(powerUpTimer / 60);
                    const puColor = POWERUP_COLORS[activePowerUp];
                    ctx.fillStyle = puColor;
                    ctx.textAlign = 'center';
                    ctx.font = '12px "Courier New", monospace';
                    const label = activePowerUp === 'widen' ? 'WIDE PADDLE' :
                        activePowerUp === 'slow' ? 'SLOW BALL' : 'MULTI-BALL';
                    ctx.fillText(`${label} ${secLeft}s`, W / 2, H - 18);
                }
            }

            function drawOverlay(title, subtitle, titleColor = '#ff00e5') {
                // Dim background
                ctx.fillStyle = 'rgba(0,0,0,0.7)';
                ctx.fillRect(0, 0, W, H);

                // Title
                ctx.fillStyle = titleColor;
                ctx.font = 'bold 42px "Courier New", monospace';
                ctx.textAlign = 'center';
                ctx.shadowColor = titleColor;
                ctx.shadowBlur = 20;
                ctx.fillText(title, W / 2, H / 2 - 30);
                ctx.shadowBlur = 0;

                // Subtitle
                ctx.fillStyle = '#ffffff';
                ctx.font = '16px "Courier New", monospace';
                ctx.fillText(subtitle, W / 2, H / 2 + 25);

                // Score display for game over / victory
                if (title === 'GAME OVER' || title === 'VICTORY!') {
                    ctx.fillStyle = '#ffe600';
                    ctx.font = 'bold 20px "Courier New", monospace';
                    ctx.fillText(`FINAL SCORE: ${score}`, W / 2, H / 2 + 60);
                    ctx.fillText(`LEVEL: ${level}`, W / 2, H / 2 + 85);
                }

                // Pulsing "click to start" text
                const pulse = 0.6 + 0.4 * Math.sin(performance.now() / 500);
                ctx.fillStyle = `rgba(255,255,255,${pulse})`;
                ctx.font = '14px "Courier New", monospace';
                const ctaText = title === 'GAME OVER' || title === 'VICTORY!' ?
                    'CLICK / TAP / SPACE TO PLAY AGAIN' :
                    'CLICK / TAP / SPACE TO START';
                ctx.fillText(ctaText, W / 2, H / 2 + (title === 'GAME OVER' || title === 'VICTORY!' ? 115 : 70));
            }

            function drawLevelTransition() {
                const alpha = levelTransitionTimer > 60 ?
                    (120 - levelTransitionTimer) / 60 :
                    levelTransitionTimer / 60;
                ctx.fillStyle = `rgba(0,0,0,${0.5 + alpha * 0.3})`;
                ctx.fillRect(0, 0, W, H);

                ctx.fillStyle = `rgba(57, 255, 20, ${alpha})`;
                ctx.font = 'bold 36px "Courier New", monospace';
                ctx.textAlign = 'center';
                ctx.shadowColor = '#39ff14';
                ctx.shadowBlur = 20 * alpha;
                ctx.fillText(`LEVEL ${level}`, W / 2, H / 2);
                ctx.shadowBlur = 0;
            }

            function draw() {
                ctx.clearRect(0, 0, W, H);

                // Apply screen shake
                let shakeX = 0;
                let shakeY = 0;
                if (shakeAmount > 0.05) {
                    shakeX = (Math.random() - 0.5) * shakeAmount * 2;
                    shakeY = (Math.random() - 0.5) * shakeAmount * 2;
                }

                ctx.save();
                ctx.translate(shakeX, shakeY);

                drawBackground();
                drawBricks();
                drawPowerUps();
                drawPaddle();
                drawBall(ball, false);
                for (const eb of extraBalls) {
                    drawBall(eb, true);
                }
                drawParticles();
                drawHUD();

                ctx.restore();

                // Overlays (not affected by shake)
                if (gameState === STATE.START) {
                    drawOverlay('BRICK BREAKER', 'NEON EDITION', '#00f0ff');
                } else if (gameState === STATE.GAME_OVER) {
                    drawOverlay('GAME OVER', 'BETTER LUCK NEXT TIME', '#ff0044');
                } else if (gameState === STATE.VICTORY) {
                    drawOverlay('VICTORY!', 'YOU CRUSHED IT!', '#39ff14');
                } else if (gameState === STATE.LEVEL_TRANSITION) {
                    drawLevelTransition();
                }
            }

            // --- Game Loop ---
            function gameLoop() {
                update();
                draw();
                requestAnimationFrame(gameLoop);
            }

            // --- Handle resize ---
            function handleResize() {
                const container = document.getElementById('game-container');
                const maxSize = Math.min(window.innerWidth, window.innerHeight);
                container.style.width = Math.min(maxSize, 800) + 'px';
                container.style.height = 'auto';
            }

            window.addEventListener('resize', handleResize);
            handleResize();

            // --- Start ---
            gameLoop();
            console.log('🔥 Neon Brick Breaker ready! Click or press Space to start.');
        })();
    </script>
</body>
</html>
