<script>
(() => {
'use strict';

// ================= CONFIG =================
const GAME_W = 800, GAME_H = 600;
const MAX_LEVEL = 3;
const ROW_COLORS = ['#ff2d78', '#ff9f1c', '#ffe600', '#2bff88', '#00cfff', '#b26bff'];
const LEVELS = [
  [
    "1111111111",
    "1111111111",
    "1111111111",
    "1111111111"
  ],
  [
    "2111111112",
    "1211111121",
    "1122112211",
    "1211111121",
    "2111111112"
  ],
  [
    "3322112233",
    "3111111113",
    "2122332212",
    "2122332212",
    "3111111113",
    "3322112233"
  ]
];
const BRICK = { gap: 6, top: 70, side: 30, h: 22, cols: 10 };

// ================= CANVAS / RESIZE =================
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
function resize() {
  const scale = Math.min(window.innerWidth / GAME_W, window.innerHeight / GAME_H);
  canvas.style.width  = Math.floor(GAME_W * scale) + 'px';
  canvas.style.height = Math.floor(GAME_H * scale) + 'px';
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width  = GAME_W * dpr;
  canvas.height = GAME_H * dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}
window.addEventListener('resize', resize);
resize();

// ================= AUDIO (Web Audio API) =================
let actx = null, muted = false;
function ensureAudio() {
  if (!actx) {
    try { actx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) {}
  }
  if (actx && actx.state === 'suspended') actx.resume();
}
function audioOK() { return !!actx && !muted; }
function tone(freq, dur, type, vol, slideTo, delay) {
  if (!audioOK()) return;
  type = type || 'sine'; vol = vol || 0.12; delay = delay || 0;
  const t = actx.currentTime + delay;
  const o = actx.createOscillator();
  const g = actx.createGain();
  o.type = type;
  o.frequency.setValueAtTime(freq, t);
  if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(slideTo, 1), t + dur);
  g.gain.setValueAtTime(vol, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  o.connect(g); g.connect(actx.destination);
  o.start(t); o.stop(t + dur + 0.05);
}
function noiseBurst(dur, vol) {
  if (!audioOK()) return;
  dur = dur || 0.1; vol = vol || 0.12;
  const len = Math.floor(actx.sampleRate * dur);
  const buf = actx.createBuffer(1, len, actx.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
  const src = actx.createBufferSource(); src.buffer = buf;
  const f = actx.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 1200;
  const g = actx.createGain(); g.gain.value = vol;
  src.connect(f); f.connect(g); g.connect(actx.destination);
  src.start();
}
const sndWall     = () => tone(180, 0.05, 'square', 0.06);
const sndPaddle   = () => tone(240, 0.07, 'square', 0.11, 380);
const sndLaunch   = () => tone(500, 0.12, 'sine', 0.12, 950);
const sndBrick    = (b) => { tone(340 + b.maxHp * 70 + Math.random() * 40, 0.09, 'triangle', 0.15); noiseBurst(0.09, 0.11); };
const sndBrickHard= () => tone(170, 0.06, 'square', 0.10, 90);
const sndLife     = () => tone(300, 0.5, 'sawtooth', 0.14, 60);
const sndLevelClear = () => [523.25, 659.25, 783.99, 1046.5].forEach((f, i) => tone(f, 0.16, 'square', 0.10, null, i * 0.09));
const sndGameOver = () => [392, 330, 262, 196].forEach((f, i) => tone(f, 0.32, 'sawtooth', 0.11, null, i * 0.18));
const sndVictory  = () => [523, 659, 784, 1047, 784, 1047, 1319].forEach((f, i) => tone(f, 0.18, 'square', 0.10, null, i * 0.11));

// ================= STATE =================
const STATE = { START: 0, SERVE: 1, PLAY: 2, LEVELCLEAR: 3, GAMEOVER: 4, VICTORY: 5 };
let state = STATE.START;
let score = 0, lives = 3, level = 1, best = 0;
let stateTimer = 0, tGlobal = 0, shake = 0, fwTimer = 0, levelBonus = 0;
try { best = parseInt(localStorage.getItem('neonBreakerBest') || '0', 10) || 0; } catch (e) {}
function saveBest() {
  if (score > best) {
    best = score;
    try { localStorage.setItem('neonBreakerBest', String(best)); } catch (e) {}
  }
}

// ================= ENTITIES =================
const paddle = { w: 110, h: 14, x: GAME_W / 2 - 55, y: GAME_H - 40, speed: 640 };
const ball = { x: 0, y: 0, r: 8, dx: 0, dy: -1, speed: 380, trail: [] };
let bricks = [];
let particles = [];
const bgDots = [];
for (let i = 0; i < 45; i++) bgDots.push({
  x: Math.random() * GAME_W, y: Math.random() * GAME_H,
  s: Math.random() * 1.6 + 0.5, v: 8 + Math.random() * 22, a: 0.12 + Math.random() * 0.3
});

function buildLevel(lv) {
  bricks = [];
  const rows = LEVELS[lv - 1];
  const w = (GAME_W - BRICK.side * 2 - BRICK.gap * (BRICK.cols - 1)) / BRICK.cols;
  paddle.w = 110 - (lv - 1) * 8;
  rows.forEach((rowStr, r) => {
    for (let c = 0; c < rowStr.length; c++) {
      const ch = rowStr[c];
      if (ch === ' ') continue;
      const hp = parseInt(ch, 10);
      bricks.push({
        x: BRICK.side + c * (w + BRICK.gap),
        y: BRICK.top + r * (BRICK.h + BRICK.gap),
        w: w, h: BRICK.h,
        hp: hp, maxHp: hp,
        color: ROW_COLORS[r % ROW_COLORS.length],
        alive: true, points: hp * 50, flash: 0
      });
    }
  });
}

function resetServe() {
  ball.trail.length = 0;
  ball.speed = 360 + (level - 1) * 55;
  paddle.x = GAME_W / 2 - paddle.w / 2;
  ball.x = paddle.x + paddle.w / 2;
  ball.y = paddle.y - ball.r - 1;
  state = STATE.SERVE;
}

function startGame() {
  score = 0; lives = 3; level = 1;
  buildLevel(1);
  resetServe();
}

function launchBall() {
  const a = -Math.PI / 2 + (Math.random() * 0.6 - 0.3);
  ball.dx = Math.cos(a);
  ball.dy = Math.sin(a);
  state = STATE.PLAY;
  sndLaunch();
}

function loseLife() {
  lives--;
  sndLife();
  shake = 9;
  if (lives <= 0) { state = STATE.GAMEOVER; saveBest(); sndGameOver(); }
  else resetServe();
}

function levelCleared() {
  if (level >= MAX_LEVEL) {
    state = STATE.VICTORY; saveBest(); sndVictory();
  } else {
    levelBonus = 200 * level;
    score += levelBonus;
    state = STATE.LEVELCLEAR;
    stateTimer = 2.1;
    sndLevelClear();
  }
}

// ================= PARTICLES =================
function spawnParticles(x, y, color, n) {
  n = n || 14;
  for (let i = 0; i < n; i++) {
    const a = Math.random() * Math.PI * 2;
    const sp = 60 + Math.random() * 280;
    particles.push({
      x: x, y: y,
      vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 70,
      life: 0.5 + Math.random() * 0.55, age: 0,
      color: color, size: 2 + Math.random() * 3.5
    });
  }
}
function updateParticles(dt) {
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.age += dt;
    if (p.age >= p.life) { particles.splice(i, 1); continue; }
    p.vy += 520 * dt;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
  }
}

// ================= INPUT =================
const keys = {};
const pointer = { x: null };
function toGameX(clientX) {
  const rect = canvas.getBoundingClientRect();
  return (clientX - rect.left) / rect.width * GAME_W;
}
function handleAction() {
  ensureAudio();
  if (state === STATE.START) startGame();
  else if (state === STATE.SERVE) launchBall();
  else if (state === STATE.GAMEOVER || state === STATE.VICTORY) state = STATE.START;
}
window.addEventListener('keydown', (e) => {
  ensureAudio();
  keys[e.code] = true;
  if (e.code === 'ArrowLeft' || e.code === 'ArrowRight' || e.code === 'Space') e.preventDefault();
  if (e.code === 'KeyM') muted = !muted;
  if (e.code === 'Space' || e.code === 'Enter') handleAction();
});
window.addEventListener('keyup', (e) => { keys[e.code] = false; });
canvas.addEventListener('mousemove', (e) => { pointer.x = toGameX(e.clientX); });
canvas.addEventListener('mousedown', (e) => { pointer.x = toGameX(e.clientX); handleAction(); });
canvas.addEventListener('touchstart', (e) => {
  e.preventDefault();
  pointer.x = toGameX(e.touches[0].clientX);
  handleAction();
}, { passive: false });
canvas.addEventListener('touchmove', (e) => {
  e.preventDefault();
  pointer.x = toGameX(e.touches[0].clientX);
}, { passive: false });

// ================= UPDATE =================
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }

function updateBall(dt) {
  const dist = ball.speed * dt;
  const steps = Math.max(1, Math.ceil(dist / (ball.r * 0.8)));
  const sdt = dt / steps;
  for (let s = 0; s < steps; s++) {
    ball.x += ball.dx * ball.speed * sdt;
    ball.y += ball.dy * ball.speed * sdt;

    // walls
    if (ball.x - ball.r < 0) { ball.x = ball.r; ball.dx = Math.abs(ball.dx); sndWall(); }
    if (ball.x + ball.r > GAME_W) { ball.x = GAME_W - ball.r; ball.dx = -Math.abs(ball.dx); sndWall(); }
    if (ball.y - ball.r < 0) { ball.y = ball.r; ball.dy = Math.abs(ball.dy); sndWall(); }

    // paddle (angle reflection based on hit position)
    if (ball.dy > 0 &&
        ball.y + ball.r >= paddle.y && ball.y - ball.r <= paddle.y + paddle.h &&
        ball.x + ball.r >= paddle.x && ball.x - ball.r <= paddle.x + paddle.w) {
      const rel = clamp((ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2), -1, 1);
      const maxAng = Math.PI * 0.38; // ~68 degrees
      const ang = rel * maxAng;
      ball.dx = Math.sin(ang);
      ball.dy = -Math.cos(ang);
      ball.y = paddle.y - ball.r - 0.1;
      sndPaddle();
    }

    // bricks
    for (const b of bricks) {
      if (!b.alive) continue;
      if (ball.x + ball.r > b.x && ball.x - ball.r < b.x + b.w &&
          ball.y + ball.r > b.y && ball.y - ball.r < b.y + b.h) {
        const oL = (ball.x + ball.r) - b.x;
        const oR = (b.x + b.w) - (ball.x - ball.r);
        const oT = (ball.y + ball.r) - b.y;
        const oB = (b.y + b.h) - (ball.y - ball.r);
        const mX = Math.min(oL, oR), mY = Math.min(oT, oB);
        if (mX < mY) {
          ball.dx = oL < oR ? -Math.abs(ball.dx) : Math.abs(ball.dx);
          ball.x += oL < oR ? -mX : mX;
        } else {
          ball.dy = oT < oB ? -Math.abs(ball.dy) : Math.abs(ball.dy);
          ball.y += oT < oB ? -mY : mY;
        }
        hitBrick(b);
        break;
      }
    }

    if (state !== STATE.PLAY) return;
    if (ball.y - ball.r > GAME_H) { loseLife(); return; }
  }
  ball.trail.push({ x: ball.x, y: ball.y });
  if (ball.trail.length > 12) ball.trail.shift();
}

function hitBrick(b) {
  b.hp--;
  b.flash = 1;
  if (b.hp <= 0) {
    b.alive = false;
    score += b.points;
    spawnParticles(b.x + b.w / 2, b.y + b.h / 2, b.color, 16);
    sndBrick(b);
    shake = Math.min(shake + 1.6, 4);
    ball.speed = Math.min(ball.speed + 2.5, 640);
    if (bricks.every(x => !x.alive)) levelCleared();
  } else {
    sndBrickHard();
    spawnParticles(ball.x, ball.y, b.color, 5);
  }
}

function update(dt) {
  tGlobal += dt;
  shake = Math.max(0, shake - dt * 22);

  for (const d of bgDots) {
    d.y += d.v * dt;
    if (d.y > GAME_H) { d.y = -2; d.x = Math.random() * GAME_W; }
  }
  for (const b of bricks) if (b.flash > 0) b.flash = Math.max(0, b.flash - dt * 4);
  updateParticles(dt);

  if (state === STATE.SERVE || state === STATE.PLAY) {
    if (pointer.x != null) {
      paddle.x = clamp(pointer.x - paddle.w / 2, 0, GAME_W - paddle.w);
    }
    const kb = (keys.ArrowRight || keys.KeyD ? 1 : 0) - (keys.ArrowLeft || keys.KeyA ? 1 : 0);
    if (kb !== 0) {
      paddle.x = clamp(paddle.x + kb * paddle.speed * dt, 0, GAME_W - paddle.w);
      pointer.x = null;
    }
  }
  if (state === STATE.SERVE) {
    ball.x = paddle.x + paddle.w / 2;
    ball.y = paddle.y - ball.r - 1;
  }
  if (state === STATE.PLAY) updateBall(dt);

  if (state === STATE.LEVELCLEAR) {
    stateTimer -= dt;
    if (stateTimer <= 0) {
      level++;
      buildLevel(level);
      resetServe();
    }
  }
  if (state === STATE.VICTORY) {
    fwTimer -= dt;
    if (fwTimer <= 0) {
      fwTimer = 0.28;
      spawnParticles(
        80 + Math.random() * (GAME_W - 160),
        60 + Math.random() * 220,
        ROW_COLORS[Math.floor(Math.random() * ROW_COLORS.length)], 22);
    }
  }
}

// ================= DRAW =================
function roundRect(x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}
function neonText(text, x, y, size, color, alpha) {
  ctx.save();
  if (alpha !== undefined) ctx.globalAlpha = alpha;
  ctx.font = 'bold ' + size + 'px "Segoe UI", Arial, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.shadowColor = color;
  ctx.shadowBlur = 22;
  ctx.fillStyle = color;
  ctx.fillText(text, x, y);
  ctx.restore();
}

function drawBackground() {
  ctx.save();
  ctx.strokeStyle = 'rgba(0,229,255,0.05)';
  ctx.lineWidth = 1;
  for (let x = 0; x <= GAME_W; x += 40) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_H); ctx.stroke(); }
  for (let y = 0; y <= GAME_H; y += 40) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_W, y); ctx.stroke(); }
  for (const d of bgDots) {
    ctx.globalAlpha = d.a;
    ctx.fillStyle = '#9adfff';
    ctx.fillRect(d.x, d.y, d.s, d.s);
  }
  ctx.globalAlpha = 1;
  ctx.shadowColor = '#00e5ff';
  ctx.shadowBlur = 10;
  ctx.strokeStyle = 'rgba(0,229,255,0.35)';
  ctx.lineWidth = 2;
  ctx.strokeRect(1, 1, GAME_W - 2, GAME_H - 2);
  ctx.restore();
}

function drawBricks() {
  for (const b of bricks) {
    if (!b.alive) continue;
    ctx.save();
    ctx.shadowColor = b.color;
    ctx.shadowBlur = 12 + b.flash * 24;
    ctx.fillStyle = b.color;
    roundRect(b.x, b.y, b.w, b.h, 4);
    ctx.fill();
    ctx.shadowBlur = 0;
    const g = ctx.createLinearGradient(0, b.y, 0, b.y + b.h);
    g.addColorStop(0, 'rgba(255,255,255,0.45)');
    g.addColorStop(0.5, 'rgba(255,255,255,0.05)');
    g.addColorStop(1, 'rgba(0,0,0,0.28)');
    ctx.fillStyle = g;
    roundRect(b.x, b.y, b.w, b.h, 4);
    ctx.fill();
    if (b.maxHp > 1) {
      ctx.strokeStyle = 'rgba(255,255,255,' + (0.2 + 0.5 * (b.hp / b.maxHp)) + ')';
      ctx.lineWidth = 2;
      roundRect(b.x + 3.5, b.y + 3.5, b.w - 7, b.h - 7, 3);
      ctx.stroke();
    }
    ctx.restore();
  }
}

function drawParticles() {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (const p of particles) {
    ctx.globalAlpha = Math.max(0, 1 - p.age / p.life);
    ctx.shadowColor = p.color;
    ctx.shadowBlur = 8;
    ctx.fillStyle = p.color;
    ctx.fillRect(p.x - p.size / 2, p.y - p.size / 2, p.size, p.size);
  }
  ctx.restore();
}

function drawPaddle() {
  ctx.save();
  ctx.shadowColor = '#00e5ff';
  ctx.shadowBlur = 18;
  const g = ctx.createLinearGradient(0, paddle.y, 0, paddle.y + paddle.h);
  g.addColorStop(0, '#9ffbff');
  g.addColorStop(0.5, '#00e5ff');
  g.addColorStop(1, '#0066ff');
  ctx.fillStyle = g;
  roundRect(paddle.x, paddle.y, paddle.w, paddle.h, 7);
  ctx.fill();
  ctx.restore();
}

function drawBall() {
  for (let i = 0; i < ball.trail.length; i++) {
    const t = ball.trail[i];
    const f = i / ball.trail.length;
    ctx.fillStyle = 'rgba(0,229,255,' + (f * 0.28) + ')';
    ctx.beginPath();
    ctx.arc(t.x, t.y, ball.r * f, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.save();
  ctx.shadowColor = '#aefcff';
  ctx.shadowBlur = 20;
  const g = ctx.createRadialGradient(ball.x - 2, ball.y - 2, 1, ball.x, ball.y, ball.r);
  g.addColorStop(0, '#ffffff');
  g.addColorStop(1, '#00e5ff');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function drawHUD() {
  ctx.save();
  ctx.font = 'bold 17px "Segoe UI", Arial, sans-serif';
  ctx.textBaseline = 'top';
  ctx.shadowColor = '#00e5ff';
  ctx.shadowBlur = 8;
  ctx.fillStyle = '#aefcff';
  ctx.textAlign = 'left';
  ctx.fillText('SCORE ' + score, 16, 12);
  ctx.textAlign = 'center';
  ctx.fillText('LEVEL ' + level + '/' + MAX_LEVEL, GAME_W / 2, 12);
  for (let i = 0; i < lives; i++) {
    const x = GAME_W - 22 - i * 20, y = 21;
    ctx.beginPath();
    ctx.arc(x, y, 6, 0, Math.PI * 2);
    ctx.fillStyle = '#00e5ff';
    ctx.fill();
  }
  if (muted) {
    ctx.shadowBlur = 0;
    ctx.textAlign = 'right';
    ctx.fillStyle = 'rgba(255,255,255,0.4)';
    ctx.font = '12px "Segoe UI", Arial, sans-serif';
    ctx.fillText('SOUND OFF (M)', GAME_W - 12, GAME_H - 22);
  }
  ctx.restore();
}

function overlay() {
  ctx.fillStyle = 'rgba(3,3,14,0.8)';
  ctx.fillRect(0, 0, GAME_W, GAME_H);
}
function blinkAlpha() { return 0.5 + 0.5 * Math.sin(tGlobal * 5); }

function drawStart() {
  overlay();
  neonText('NEON', GAME_W / 2, 150, 74, '#00e5ff');
  neonText('BREAKER', GAME_W / 2, 224, 74, '#ff2d78');
  // decorative brick strip
  const w = 62, h = 16;
  for (let i = 0; i < 6; i++) {
    const x = GAME_W / 2 - (6 * (w + 8) - 8) / 2 + i * (w + 8);
    ctx.save();
    ctx.shadowColor = ROW_COLORS[i];
    ctx.shadowBlur = 14;
    ctx.fillStyle = ROW_COLORS[i];
    roundRect(x, 288, w, h, 4);
    ctx.fill();
    ctx.restore();
  }
  neonText('MOUSE / ARROW KEYS / TOUCH — MOVE PADDLE', GAME_W / 2, 356, 17, '#9adfff', 0.9);
  neonText('CLICK / SPACE / TAP — LAUNCH BALL', GAME_W / 2, 386, 17, '#9adfff', 0.9);
  neonText('M — TOGGLE SOUND', GAME_W / 2, 416, 17, '#9adfff', 0.9);
  if (best > 0) neonText('BEST: ' + best, GAME_W / 2, 452, 18, '#ffe600');
  neonText('— CLICK TO START —', GAME_W / 2, 502, 22, '#2bff88', blinkAlpha());
}

function drawServeHint() {
  neonText('CLICK / SPACE TO LAUNCH', GAME_W / 2, GAME_H - 92, 16, '#7df9ff', blinkAlpha());
}
function drawLevelClear() {
  overlay();
  neonText('LEVEL ' + level + ' CLEARED!', GAME_W / 2, 250, 46, '#2bff88');
  neonText('BONUS +' + levelBonus, GAME_W / 2, 310, 24, '#ffe600');
  neonText('GET READY...', GAME_W / 2, 370, 18, '#9adfff', blinkAlpha());
}
function drawGameOver() {
  overlay();
  neonText('GAME OVER', GAME_W / 2, 230, 58, '#ff2d78');
  neonText('SCORE: ' + score, GAME_W / 2, 310, 26, '#aefcff');
  neonText('BEST:  ' + best, GAME_W / 2, 348, 22, '#ffe600');
  neonText('— CLICK TO CONTINUE —', GAME_W / 2, 430, 20, '#2bff88', blinkAlpha());
}
function drawVictory() {
  overlay();
  neonText('YOU WIN!', GAME_W / 2, 220, 64, '#ffe600');
  neonText('ALL LEVELS CLEARED', GAME_W / 2, 285, 22, '#2bff88');
  neonText('SCORE: ' + score, GAME_W / 2, 340, 26, '#aefcff');
  neonText('BEST:  ' + best, GAME_W / 2, 378, 22, '#ffe600');
  neonText('— CLICK TO CONTINUE —', GAME_W / 2, 450, 20, '#2bff88', blinkAlpha());
}

function draw() {
  ctx.save();
  ctx.fillStyle = '#05050f';
  ctx.fillRect(0, 0, GAME_W, GAME_H);
  if (shake > 0.2) ctx.translate((Math.random() - 0.5) * shake, (Math.random() - 0.5) * shake);
  drawBackground();
  drawBricks();
  drawParticles();
  if (state !== STATE.START) {
    drawPaddle();
    drawBall();
    drawHUD();
  }
  ctx.restore();

  if (state === STATE.START) drawStart();
  else if (state === STATE.SERVE) drawServeHint();
  else if (state === STATE.LEVELCLEAR) drawLevelClear();
  else if (state === STATE.GAMEOVER) drawGameOver();
  else if (state === STATE.VICTORY) drawVictory();
}

// ================= MAIN LOOP =================
let last = performance.now();
function loop(now) {
  let dt = (now - last) / 1000;
  last = now;
  dt = Math.min(dt, 1 / 30);
  update(dt);
  draw();
  requestAnimationFrame(loop);
}
buildLevel(1); // background bricks visible behind the start screen
requestAnimationFrame(loop);

})();
</script>
</body>
</html>
```

**Features included:**

- **Physics** — angle-based paddle reflection (hit position controls bounce angle up to ~68°), sub-stepped movement to prevent tunneling at high speeds, axis-resolved brick collision so the ball bounces off the correct side, and gradual ball speed ramping.
- **Controls** — mouse, arrow keys / A-D, and touch (drag to move, tap to launch). Space/Enter/click to launch and navigate menus.
- **Bricks** — 3 hand-designed levels with 1HP, 2HP, and 3HP bricks (inner ring shows remaining durability), per-row neon colors.
- **Game flow** — start screen, serve state, level-clear transition with bonus points, game over, and victory screens, plus a persistent best score via localStorage.
- **Particles** — glowing debris bursts with gravity on brick destruction, a ball trail, ambient drifting starfield, screen shake, and victory fireworks.
- **Sound** — fully synthesized Web Audio effects (paddle/wall blips, pitched brick shatters with noise bursts, life-lost sweep, arpeggios for level clear/victory/game over). Press M to mute.
- **Responsive** — fixed 800×600 logical resolution scaled to any window with devicePixelRatio-aware rendering, so it stays crisp on phones and desktops.

