    text-align: center;
  }

  .overlay .subtitle {
    font-family: 'Rajdhani', sans-serif;
    font-size: 20px;
    color: rgba(255,255,255,0.7);
    letter-spacing: 4px;
    margin-bottom: 40px;
  }

  .btn {
    position: relative;
    padding: 16px 48px;
    font-family: 'Orbitron', sans-serif;
    font-size: 18px;
    letter-spacing: 4px;
    text-transform: uppercase;
    color: #fff;
    background: transparent;
    border: 2px solid var(--neon-cyan);
    border-radius: 4px;
    cursor: pointer;
    overflow: hidden;
    transition: all 0.3s ease;
    box-shadow: 0 0 15px rgba(0,240,255,0.3), inset 0 0 15px rgba(0,240,255,0.1);
  }

  .btn::before {
    content: "";
    position: absolute;
    top: 0; left: -100%;
    width: 100%; height: 100%;
    background: linear-gradient(90deg, transparent, rgba(0,240,255,0.2), transparent);
    transition: left 0.5s ease;
  }

  .btn:hover {
    background: rgba(0,240,255,0.1);
    box-shadow: 0 0 30px rgba(0,240,255,0.5), inset 0 0 20px rgba(0,240,255,0.2);
    transform: translateY(-2px);
  }

  .btn:hover::before { left: 100%; }

  .overlay .stats-row {
    display: flex;
    gap: 40px;
    margin-top: 30px;
    font-family: 'Rajdhani', sans-serif;
    font-size: 14px;
    color: rgba(255,255,255,0.5);
  }

  .stats-row span { color: var(--neon-lime); text-shadow: 0 0 8px var(--neon-lime); }

  /* Controls hint */
  #controlsHint {
    position: absolute;
    bottom: 16px;
    left: 0; right: 0;
    text-align: center;
    font-family: 'Rajdhani', sans-serif;
    font-size: 12px;
    color: rgba(255,255,255,0.3);
    pointer-events: none;
    letter-spacing: 1px;
  }

  @media (max-width: 640px) {
    #hud { padding: 10px 12px; font-size: 12px; }
    .hud-val { font-size: 16px; }
    .overlay h1 { font-size: 48px; letter-spacing: 4px; }
  }
</style>
</head>
<body>

<div id="gameWrap">
  <div id="hud">
    <div class="hud-item">
      <div><span class="hud-label">SCORE</span><br><span class="hud-val" id="scoreVal">0</span></div>
      <div><span class="hud-label">LEVEL</span><br><span class="hud-val" id="levelVal">1</span></div>
    </div>
    <div class="hud-item">
      <div><span class="hud-label">LIVES</span><br><span class="hud-val" id="livesVal">3</span></div>
    </div>
  </div>

  <canvas id="gameCanvas"></canvas>

  <div id="startOverlay" class="overlay">
    <h1>NEON BREAKER</h1>
    <div class="subtitle">BREAK THE GRID</div>
    <button class="btn" id="startBtn">START GAME</button>
    <div class="stats-row">
      <span>MOUSE / TOUCH / ARROWS</span>
    </div>
  </div>

  <div id="gameOverOverlay" class="overlay hidden">
    <h1 style="background: linear-gradient(135deg, var(--neon-pink), var(--neon-violet)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text;">GAME OVER</h1>
    <div class="subtitle">FINAL SCORE: <span id="finalScore">0</span></div>
    <button class="btn" id="restartBtn">TRY AGAIN</button>
  </div>

  <div id="victoryOverlay" class="overlay hidden">
    <h1 style="background: linear-gradient(135deg, var(--neon-lime), var(--neon-cyan)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text;">VICTORY</h1>
    <div class="subtitle">LEVEL COMPLETE</div>
    <button class="btn" id="nextBtn">NEXT LEVEL</button>
  </div>

  <div id="controlsHint">MOVE PADDLE • BREAK BRICKS • SURVIVE</div>
</div>

<script>
/* =========================================================
   NEON BREAKER - Self-contained Canvas Game
   ========================================================= */

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// Audio context
let audioCtx;
function initAudio() {
  if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  if (audioCtx.state === 'suspended') audioCtx.resume();
}

// Synthesized sounds
function playSound(type, freq = 440, duration = 0.1, gain = 0.1) {
  if (!audioCtx) return;
  try {
    const osc = audioCtx.createOscillator();
    const g = audioCtx.createGain();
    osc.connect(g);
    g.connect(audioCtx.destination);
    osc.type = type === 'bounce' ? 'triangle' : type === 'break' ? 'square' : 'sine';
    osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
    g.gain.setValueAtTime(gain, audioCtx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + duration);
    osc.start();
    osc.stop(audioCtx.currentTime + duration);
  } catch (e) {}
}

// Game state
let W, H;
let running = false;
let gameOver = false;
let victory = false;
let level = 1;
let score = 0;
let lives = 3;
let animId;

const ball = { x: 0, y: 0, r: 8, dx: 4, dy: -4, speed: 5 };
const paddle = { w: 100, h: 14, x: 0, y: 0, color: '#00f0ff' };

let bricks = [];
let particles = [];
let keys = {};
let mouseX = 0;

// Resize
function resize() {
  const wrap = document.getElementById('gameWrap');
  const rect = wrap.getBoundingClientRect();
  const maxW = Math.min(rect.width, 1000);
  const maxH = Math.min(rect.height, 800);
  canvas.width = maxW;
  canvas.height = maxH;
  W = canvas.width;
  H = canvas.height;
  resetPositions();
}
window.addEventListener('resize', resize);

// Input
window.addEventListener('keydown', e => { keys[e.key] = true; if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key)) e.preventDefault(); });
window.addEventListener('keyup', e => keys[e.key] = false);
canvas.addEventListener('mousemove', e => {
  const rect = canvas.getBoundingClientRect();
  mouseX = e.clientX - rect.left;
});
canvas.addEventListener('touchmove', e => {
  e.preventDefault();
  const rect = canvas.getBoundingClientRect();
  mouseX = e.touches[0].clientX - rect.left;
}, { passive: false });
canvas.addEventListener('touchstart', e => {
  e.preventDefault();
  const rect = canvas.getBoundingClientRect();
  mouseX = e.touches[0].clientX - rect.left;
}, { passive: false });

// Reset positions
function resetPositions() {
  ball.x = W / 2;
  ball.y = H - 80;
  ball.dx = 4 * (Math.random() > 0.5 ? 1 : -1);
  ball.dy = -4;
  paddle.x = W / 2 - paddle.w / 2;
  paddle.y = H - 30;
}

// Brick setup
function buildBricks() {
  bricks = [];
  const rows = 5 + Math.min(level, 5);
  const cols = 9;
  const brickW = (W - 60) / cols;
  const brickH = 22;
  const colors = ['#00f0ff', '#ff0090', '#aaff00', '#b000ff', '#ffcc00'];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      bricks.push({
        x: 30 + c * (brickW + 4),
        y: 60 + r * (brickH + 6),
        w: brickW,
        h: brickH,
        active: true,
        color: colors[r % colors.length],
        hits: 1
      });
    }
  }
}

// Particles
function spawnParticles(x, y, color) {
  for (let i = 0; i < 12; i++) {
    const angle = (Math.PI * 2 / 12) * i;
    particles.push({
      x, y,
      vx: Math.cos(angle) * (2 + Math.random() * 3),
      vy: Math.sin(angle) * (2 + Math.random() * 3),
      life: 1,
      color
    });
  }
}

// Update particles
function updateParticles() {
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.vy += 0.1;
    p.life -= 0.03;
    if (p.life <= 0) particles.splice(i, 1);
  }
}

// Draw particles
function drawParticles() {
  for (const p of particles) {
    ctx.save();
    ctx.globalAlpha = p.life;
    ctx.fillStyle = p.color;
    ctx.shadowColor = p.color;
    ctx.shadowBlur = 10;
    ctx.fillRect(p.x - 3, p.y - 3, 6, 6);
    ctx.restore();
  }
}

// Update ball
function updateBall() {
  ball.x += ball.dx;
  ball.y += ball.dy;

  // Wall bounce
  if (ball.x - ball.r < 0 || ball.x + ball.r > W) {
    ball.dx *= -1;
    ball.x = Math.max(ball.r, Math.min(W - ball.r, ball.x));
    playSound('bounce', 300, 0.08, 0.05);
  }
  if (ball.y - ball.r < 0) {
    ball.dy *= -1;
    ball.y = ball.r;
    playSound('bounce', 400, 0.08, 0.05);
  }

  // Paddle collision
  if (ball.y + ball.r > paddle.y && ball.y - ball.r < paddle.y + paddle.h &&
      ball.x > paddle.x && ball.x < paddle.x + paddle.w) {
    // Angle reflection based on hit position
    const hitPoint = ball.x - (paddle.x + paddle.w / 2);
    const angle = (hitPoint / (paddle.w / 2)) * (Math.PI / 3); // max 60 deg
    const speed = Math.sqrt(ball.dx * ball.dx + ball.dy * ball.dy);
    ball.dx = speed * Math.sin(angle);
    ball.dy = -speed * Math.cos(angle);
    ball.y = paddle.y - ball.r;
    playSound('bounce', 500 + hitPoint * 10, 0.12, 0.08);
  }

  // Bottom miss
  if (ball.y - ball.r > H) {
    lives--;
    playSound('sine', 150, 0.3, 0.08);
    if (lives <= 0) {
      endGame(false);
    } else {
      resetPositions();
      ball.dy = -Math.abs(ball.dy);
    }
  }

  // Brick collision
  for (let b of bricks) {
    if (!b.active) continue;
    if (ball.x + ball.r > b.x && ball.x - ball.r < b.x + b.w &&
        ball.y + ball.r > b.y && ball.y - ball.r < b.y + b.h) {
      b.active = false;
      score += 10 * level;
      spawnParticles(b.x + b.w / 2, b.y + b.h / 2, b.color);
      playSound('break', 600 + Math.random() * 400, 0.15, 0.08);

      // Determine bounce direction
      const overlapX = (ball.x < b.x + b.w / 2) ? (ball.x + ball.r) - b.x : (b.x + b.w) - (ball.x - ball.r);
      const overlapY = (ball.y < b.y + b.h / 2) ? (ball.y + ball.r) - b.y : (b.y + b.h) - (ball.y - ball.r);
      if (overlapX < overlapY) {
        ball.dx *= -1;
      } else {
        ball.dy *= -1;
      }
      break;
    }
  }

  // Check victory
  if (bricks.every(b => !b.active)) {
    endGame(true);
  }
}

// Update paddle
function updatePaddle() {
  // Mouse / touch
  paddle.x = mouseX - paddle.w / 2;
  // Keyboard override
  if (keys['ArrowLeft']) paddle.x -= 8;
  if (keys['ArrowRight']) paddle.x += 8;
  // Clamp
  paddle.x = Math.max(0, Math.min(W - paddle.w, paddle.x));
}

// Draw
function draw() {
  // Clear with slight trail for neon glow effect
  ctx.fillStyle = 'rgba(5, 5, 16, 0.25)';
  ctx.fillRect(0, 0, W, H);

  // Bricks
  for (const b of bricks) {
    if (!b.active) continue;
    ctx.save();
    ctx.fillStyle = b.color;
    ctx.shadowColor = b.color;
    ctx.shadowBlur = 15;
    ctx.fillRect(b.x, b.y, b.w, b.h);
    // Inner glow line
    ctx.strokeStyle = 'rgba(255,255,255,0.3)';
    ctx.lineWidth = 1;
    ctx.strokeRect(b.x + 1, b.y + 1, b.w - 2, b.h - 2);
    ctx.restore();
  }

  // Paddle
  ctx.save();
  ctx.fillStyle = paddle.color;
  ctx.shadowColor = paddle.color;
  ctx.shadowBlur = 20;
  ctx.fillRect(paddle.x, paddle.y, paddle.w, paddle.h);
  // Gradient top
  const grad = ctx.createLinearGradient(paddle.x, paddle.y, paddle.x, paddle.y + paddle.h);
  grad.addColorStop(0, 'rgba(255,255,255,0.6)');
  grad.addColorStop(1, 'rgba(0,240,255,0.2)');
  ctx.fillStyle = grad;
  ctx.fillRect(paddle.x, paddle.y, paddle.w, 3);
  ctx.restore();

  // Ball
  ctx.save();
  ctx.fillStyle = '#fff';
  ctx.shadowColor = '#00f0ff';
  ctx.shadowBlur = 15;
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // Particles
  drawParticles();

  // HUD updates
  document.getElementById('scoreVal').textContent = score;
  document.getElementById('levelVal').textContent = level;
  document.getElementById('livesVal').textContent = lives;
}

// Loop
function loop() {
  if (!running || gameOver || victory) return;
  updateBall();
  updatePaddle();
  updateParticles();
  draw();
  animId = requestAnimationFrame(loop);
}

// Start / End
function startGame() {
  initAudio();
  level = 1;
  score = 0;
  lives = 3;
  buildBricks();
  resetPositions();
  running = true;
  gameOver = false;
  victory = false;
  document.getElementById('startOverlay').classList.add('hidden');
  document.getElementById('gameOverOverlay').classList.add('hidden');
  document.getElementById('victoryOverlay').classList.add('hidden');
  loop();
}

function endGame(win) {
  running = false;
  victory = win;
  gameOver = !win;
  cancelAnimationFrame(animId);
  if (win) {
    playSound('sine', 880, 0.5, 0.1);
    setTimeout(() => playSound('sine', 1100, 0.5, 0.1), 150);
    setTimeout(() => playSound('sine', 1320, 0.8, 0.1), 300);
    document.getElementById('victoryOverlay').classList.remove('hidden');
    document.getElementById('finalScore').textContent = score;
  } else {
    playSound('sine', 100, 0.6, 0.15);
    document.getElementById('gameOverOverlay').classList.remove('hidden');
    document.getElementById('finalScore').textContent = score;
  }
}

// Buttons
document.getElementById('startBtn').addEventListener('click', () => {
  initAudio();
  startGame();
});
document.getElementById('restartBtn').addEventListener('click', () => {
  initAudio();
  startGame();
});
document.getElementById('nextBtn').addEventListener('click', () => {
  initAudio();
  level++;
  score += 500;
  buildBricks();
  resetPositions();
  running = true;
  victory = false;
  document.getElementById('victoryOverlay').classList.add('hidden');
  loop();
});

// Init
resize();
buildBricks();
resetPositions();
draw();

</script>
</body>
</html>
